private async findCustomerByCode(
  customerCode: string,
): Promise<Customer | null> {
  try {
    const customers = await this.prismaRead.customer.findMany({
      where: {
        data: {
          path: ["customerCode"],
          equals: customerCode,
        },
      },
      take: 1,
    });

    return customers.length > 0 ? customers[0] : null;
  } catch (error) {
    this.logger.error(
      `Error finding customer by code ${customerCode}:`,
      error,
    );
    return null;
  }
}
```

**Query Logic** (lines 183-189):
- Searches `Customer.data` JSON field
- Uses PostgreSQL path operator `["customerCode"]` for JSON path query
- Takes first match (typically unique)
- Searches in JSON structure: `data.customerCode`

