/**
 * Bulk operation audit optimization for better performance
 */
async createBulkAuditLogs(
  auditPayloads: any[],
  batchSize: number = 10,
): Promise<{ successful: number; failed: number; errors: any[] }> {
  const results = { successful: 0, failed: 0, errors: [] as any[] };

  // Process in batches to avoid overwhelming the database
  for (let i = 0; i < auditPayloads.length; i += batchSize) {
    const batch = auditPayloads.slice(i, i + batchSize);

    // Process batch items in parallel
    const batchPromises = batch.map(async (payload, index) => {
      try {
        await this.createAuditLogWithRetry(payload, 2); // Fewer retries for bulk operations
        return { success: true, index: i + index };
      } catch (error: any) {
        return { success: false, index: i + index, error };
      }
    });

    const batchResults = await Promise.allSettled(batchPromises);

    batchResults.forEach((result, batchIndex) => {
      if (result.status === "fulfilled") {
        if (result.value.success) {
          results.successful++;
        } else {
          results.failed++;
          results.errors.push({
            index: result.value.index,
            error: result.value.error,
          });
        }
      } else {
        results.failed++;
        results.errors.push({
          index: i + batchIndex,
          error: result.reason,
        });
      }
    });
  }

  this.logger.log(
    `Bulk audit operation completed: ${results.successful} successful, ${results.failed} failed`,
  );

  return results;
}
```

**Batch Features** (lines 2233-2284):
- **Batching**: Processes items in configurable batch size (default: 10)
- **Parallel Within Batch**: Uses `Promise.allSettled()` for parallel retry attempts
- **Partial Failure Handling**: Tracks successes and failures separately
- **Non-Atomic**: Batches can partially succeed/fail (unlike `$transaction`)

