private detectChangeAreas(commits: GitHubCommit[]): {
  hasBackend: boolean;
  hasFrontend: boolean;
} {
  let hasBackend = false;
  let hasFrontend = false;

  const backendPatterns = [
    /\bbackend\b/i,
    /\bapi\b/i,
    /\bserver\b/i,
    /\bprisma\b/i,
    /\bdatabase\b/i,
    /\bdb\b/i,
    /apps\/whk-wms\//i,        // Backend app folder pattern
    /\.service\.ts/i,
    /\.controller\.ts/i,
    /\.resolver\.ts/i,
    /\.module\.ts/i,
  ];

  const frontendPatterns = [
    /\bfrontend\b/i,
    /\bui\b/i,
    /\bcomponent/i,
    /\breact\b/i,
    /apps\/whk-wms-front-end\//i,  // Frontend app folder pattern
    /\.tsx$/i,
    /\bpage\b/i,
  ];

  for (const commit of commits) {
    const message = commit.commit.message;
    if (backendPatterns.some((pattern) => pattern.test(message))) {
      hasBackend = true;
    }
    if (frontendPatterns.some((pattern) => pattern.test(message))) {
      hasFrontend = true;
    }
  }

  // Default to both if indeterminate
  if (!hasBackend && !hasFrontend && commits.length > 0) {
    hasBackend = true;
    hasFrontend = true;
  }

  return { hasBackend, hasFrontend };
}
```

- **Regex pattern matching**: Tests commit messages against 11 backend patterns and 7 frontend patterns
- **File path detection**: Identifies `apps/whk-wms/` and `apps/whk-wms-front-end/` folders
- **Conservative fallback**: Marks both areas as changed if patterns don't match

### 5. **GitHub Commit Fetching** (Lines 325-342)
Retrieves commits between two releases using GitHub's compare API:

```
apps/whk-wms/src/changelog/changelog-sync.service.ts:325-342
private async fetchCommitsForRelease(
  release: GitHubRelease,
  allReleases: GitHubRelease[],
): Promise<GitHubCommit[]> {
  // Find the previous release to compare
  const sortedReleases = [...allReleases].sort(
    (a, b) =>
      new Date(b.published_at).getTime() - new Date(a.published_at).getTime(),
  );

  const currentIndex = sortedReleases.findIndex(
    (r) => r.tag_name === release.tag_name,
  );

  if (currentIndex === -1) {
    return [];
  }

  const previousRelease = sortedReleases[currentIndex + 1];

  if (!previousRelease) {
    return [];  // First release, no previous to compare
  }

  const url = `${this.githubApiBase}/repos/${this.owner}/${this.repo}/compare/${previousRelease.tag_name}...${release.tag_name}`;
```

- **Incremental comparison**: Compares each release to the previous one
- **API endpoint**: Uses GitHub's `/compare/{base}...{head}` endpoint
- **Safe defaults**: Returns empty array for first release (nothing to compare)

