startSession(
  sessionId: string,
  userId?: string,
  correlationId?: string,
  metadata?: Record<string, any>,
): SessionAuditTrail {
  const context = this.contextService.getFullContext();
  const enhancedUserId = userId || context?.userId || "system";
  const enhancedCorrelationId =
    correlationId ||
    context?.correlationId ||
    this.auditService.generateCorrelationId();

  let session = this.activeSessions.get(sessionId);

  if (!session) {
    session = {
      sessionId,
      userId: enhancedUserId,
      correlationId: enhancedCorrelationId,
      startTime: new Date(),
      operations: [],
      // ...
    };

    this.activeSessions.set(sessionId, session);

    // Set correlation ID in context for this session
    this.contextService.setCorrelationId(enhancedCorrelationId);

    if (metadata) {
      this.contextService.setOperationMetadata({ sessionMetadata: metadata });
    }
  }

  return session;
}
```

- **Context-aware defaults**: Falls back to context's correlation ID
- **Cascading fallbacks**: Session param → context → generated
