**apps/whk-wms/src/inventory-upload/gateways/progress.gateway.ts (lines 22-95)**

For use cases requiring custom real-time communication, dedicated Socket.IO gateways handle connection lifecycle:

```typescript
@Injectable()
@WebSocketGateway({
  namespace: "/progress",
  cors: {
    origin: process.env.FRONTEND_URL || "http://localhost:3000",
    credentials: true,
  },
  transports: ["websocket", "polling"],
})
export class ProgressGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer() server!: Server;

  // Track active connections and their subscriptions
  private readonly activeConnections = new Map<string, AuthenticatedSocket>();
  private readonly sessionSubscriptions = new Map<string, Set<string>>();

  async handleConnection(client: AuthenticatedSocket) {
    // Extract and verify JWT token from handshake
    const token = client.handshake.auth?.token || 
      client.handshake.headers?.authorization?.replace("Bearer ", "");

    const payload = await this.jwtService.verifyAsync(token);
    client.userId = payload.sub;
    this.activeConnections.set(client.id, client);
  }

  handleDisconnect(client: AuthenticatedSocket) {
    // Clean up session subscriptions
    if (client.sessionIds) {
      for (const sessionId of client.sessionIds) {
        this.unsubscribeFromSession(client.id, sessionId);
      }
    }
    this.activeConnections.delete(client.id);
  }
}
```

**apps/whk-wms/src/agent/gateways/agent-streaming.gateway.ts (lines 49-90)**

