  const conflict = locationValidationResult.locationConflict;

  this.logger.log(
    `[LocationAlreadyOccupied] Auto-resolving conflict: Orphaning barrel ` +
      `${conflict.occupyingBarrelSN} to make room for ${barrelSN} at ${locationString}`,
  );

