### Asynchronous Error Logging

**apps/whk-wms/src/barrelEvent/barrelEvent.service.ts (lines 800-865)**

Errors are logged **after** the transaction completes to avoid deadlocks:

```typescript
try {
  const result = tx
    ? await executeWithTransaction(tx)
    : await this.prisma.$androidSyncTransaction(executeWithTransaction);

  // Log LocationAlreadyOccupied error AFTER transaction completes
  if (locationOccupiedError) {
    try {
      await this.errorLogger.logError(locationOccupiedError);
      this.logger.log(
        `✅ LocationAlreadyOccupied error logged successfully after transaction`,
      );
    } catch (error) {
      this.logger.error(
        `❌ Failed to log LocationAlreadyOccupied error after transaction:`,
        error,
      );
    }
  }

  // Log BarrelCreatedByBruteForce warning AFTER transaction completes
  // Only log here if we created our own transaction (tx was NOT provided)
  if (bruteForceWarning && !tx) {
    try {
      await this.errorLogger.logError(bruteForceWarning);
      this.logger.log(
        `✅ BarrelCreatedByBruteForce warning logged successfully after transaction`,
      );
    } catch (error) {
      this.logger.error(
        `❌ Failed to log BarrelCreatedByBruteForce warning after transaction:`,
        error,
      );
    }
  } else if (bruteForceWarning && tx) {
    // tx was provided - attach to result for processor to handle
    this.logger.debug(
      `[BarrelCreatedByBruteForce] Deferring warning logging to processor (tx provided)`,
    );
    (result as any).bruteForceWarningToLog = bruteForceWarning;
  }

  return result;
} catch (error) {
  // Check if error has errorToLog attached
  if (error && (error as any).errorToLog) {
    const errorToLog = (error as any).errorToLog;
    locationOccupiedError = errorToLog;

    // Only log error here if we created our own transaction (tx was NOT provided)
    // If tx WAS provided from processor, let processor's handleTransactionError do logging
    if (!tx) {
      try {
        await this.errorLogger.logError(errorToLog);
        this.logger.log(
          `✅ LocationAlreadyOccupied error logged successfully after transaction rollback`,
        );
        // Remove errorToLog to prevent duplicate logging in processor
        delete (error as any).errorToLog;
      } catch (logError) {
        this.logger.error(
          `❌ Failed to log LocationAlreadyOccupied error:`,
          logError,
        );
      }
    } else {
      // tx was provided - let processor's handleTransactionError do the logging
      this.logger.debug(
        `[LocationAlreadyOccupied] Deferring error logging to processor (tx provided)`,
      );
    }
  }

  // Re-throw the original error
  throw error;
}
```

