### Application-Level Validation with BarrelLocationConflictException

**apps/whk-wms/src/barrel/barrel.service.ts (lines 1-10 & 146-170)**

The service validates location exclusivity **before** database operations:

```typescript
/**
 * IMPORTANT CONSTRAINTS:
 *
 * 1. Location Exclusivity: A barrel cannot have both a storage location AND a holding location.
 *    - Enforced in: createBarrel, updateBarrel, createMultipleBarrels
 *    - Database constraint: chk_barrel_location_exclusive
 *
 * 2. Disposition-Location State: Disposition must match location state.
 *    - Storage location set (locationId) → disposition MUST be 'InStorage'
 *    - Holding location set (holdingLocationId) → disposition MUST be 'InHolding' or 'TransferredOffsite'
 *    - Neither location set → disposition CANNOT be 'InStorage' or 'InHolding'
 */

// In createBarrel (lines 146-170)
// Validate that barrel cannot have both storage location AND holding location
// Handle both BarrelCreateInput (uses 'location' relation) and BarrelUncheckedCreateInput (uses 'locationId')
const dataAsAny = data as any;
const hasStorageLocation: boolean = !!(
  (dataAsAny.location &&
    typeof dataAsAny.location === "object" &&
    Object.keys(dataAsAny.location).length > 0) ||
  dataAsAny.locationId !== null
);

const hasHoldingLocation: boolean = !!(
  (dataAsAny.holdingLocation &&
    typeof dataAsAny.holdingLocation === "object" &&
    Object.keys(dataAsAny.holdingLocation).length > 0) ||
  dataAsAny.holdingLocationId !== null
);

if (hasStorageLocation && hasHoldingLocation) {
  throw new BarrelLocationConflictException();
}
```

### Exception Usage in updateBarrel

**apps/whk-wms/src/barrel/barrel.service.ts (lines 603-670)**

Updates validate against current state to prevent conflicts:

```typescript
/**
 * Updates a barrel, validating location constraints and disposition rules.
 * Ensures barrels cannot have both storage and holding locations simultaneously.
 *
 * @param args Prisma barrel update arguments
 * @param barrelId Optional barrel ID for additional existence checking
 * @returns Updated barrel
 */
async updateBarrel<T extends Prisma.BarrelUpdateArgs>(
  args: Prisma.SelectSubset<T, Prisma.BarrelUpdateArgs>,
  barrelId?: string,
): Promise<PrismaBarrel> {
  // Validate that barrel cannot have both storage location AND holding location
  // Detect if we're modifying either location field (via connect, disconnect, or direct ID)
  const modifyingStorageLocation =
    args.data.location?.connect ||
    args.data.location?.disconnect ||
    args.data.locationId !== undefined;

  const modifyingHoldingLocation =
    args.data.holdingLocation?.connect ||
    args.data.holdingLocation?.disconnect ||
    args.data.holdingLocationId !== undefined;

  if (modifyingStorageLocation || modifyingHoldingLocation) {
    // Fetch current barrel state
    const currentBarrel = await this.prismaRead.barrel.findUnique({
      where: { id: args.where.id },
    });

    // ... determine willHaveStorageLocation and willHaveHoldingLocation ...

    if (willHaveStorageLocation && willHaveHoldingLocation) {
      throw new BarrelLocationConflictException();
    }

    // Determine final disposition after update
    const finalDisposition = modifyingDisposition
      ? (args.data.disposition as string | null | undefined)
      : currentBarrel.disposition;

    // Validate disposition is compatible with final location state
    this.validateDispositionLocationState(
      finalDisposition,
      willHaveStorageLocation,
      willHaveHoldingLocation,
    );
  }

  return this.prisma.barrel.update(args);
}
```

### Disposition-Location State Constraints

**apps/whk-wms/src/barrel/barrel.service.ts (lines 78-99 & 290-347)**

The system enforces complementary disposition rules:

```typescript
/**
 * Allowed dispositions when barrel has a storage location (locationId set)
 */
private static readonly STORAGE_LOCATION_DISPOSITIONS: string[] = [
  EnumBarrelDisposition.InStorage,
];

/**
 * Allowed dispositions when barrel has a holding location (holdingLocationId set)
 */
private static readonly HOLDING_LOCATION_DISPOSITIONS: string[] = [
  EnumBarrelDisposition.InHolding,
  EnumBarrelDisposition.TransferredOffsite,
];

/**
 * Forbidden dispositions when barrel has no location (both null)
 */
private static readonly NO_LOCATION_FORBIDDEN_DISPOSITIONS: string[] = [
  EnumBarrelDisposition.InStorage,
  EnumBarrelDisposition.InHolding,
];

/**
 * Validates disposition is compatible with the barrel's location state.
 * Enforced in: createBarrel, updateBarrel, createMultipleBarrels
 *
 * Rules:
 * - Storage location set (locationId) → disposition MUST be 'InStorage'
 * - Holding location set (holdingLocationId) → disposition MUST be 'InHolding' or 'TransferredOffsite'
 * - Neither location set → disposition CANNOT be 'InStorage' or 'InHolding'
 *
 * @throws BarrelDispositionLocationStateException if disposition is incompatible with location state
 */
private validateDispositionLocationState(
  disposition: string | null | undefined,
  hasStorageLocation: boolean,
  hasHoldingLocation: boolean,
): void {
  // Null disposition is only valid when neither location is set
  // Database constraint requires specific dispositions when locations are set
  if (!disposition) {
    if (hasStorageLocation) {
      throw new BarrelDispositionLocationStateException(
        null,
        "storage",
        BarrelService.STORAGE_LOCATION_DISPOSITIONS,
      );
    }
    if (hasHoldingLocation) {
      throw new BarrelDispositionLocationStateException(
        null,
        "holding",
        BarrelService.HOLDING_LOCATION_DISPOSITIONS,
      );
    }
    // Null disposition is allowed when no location is set
    return;
  }

  if (hasStorageLocation) {
    // Storage location set → disposition MUST be 'InStorage'
    if (!BarrelService.STORAGE_LOCATION_DISPOSITIONS.includes(disposition)) {
      throw new BarrelDispositionLocationStateException(
        disposition,
        "storage",
        BarrelService.STORAGE_LOCATION_DISPOSITIONS,
      );
    }
  } else if (hasHoldingLocation) {
    // Holding location set → disposition MUST be 'InHolding' or 'TransferredOffsite'
    if (!BarrelService.HOLDING_LOCATION_DISPOSITIONS.includes(disposition)) {
      throw new BarrelDispositionLocationStateException(
        disposition,
        "holding",
        BarrelService.HOLDING_LOCATION_DISPOSITIONS,
      );
    }
  } else {
    // Neither location set → disposition CANNOT be 'InStorage' or 'InHolding'
    if (
      BarrelService.NO_LOCATION_FORBIDDEN_DISPOSITIONS.includes(disposition)
    ) {
      const allowedDispositions = Object.values(EnumBarrelDisposition).filter(
        (d) =>
          !BarrelService.NO_LOCATION_FORBIDDEN_DISPOSITIONS.includes(d),
      );
      throw new BarrelDispositionLocationStateException(
        disposition,
        "neither",
        allowedDispositions,
      );
    }
  }
}
