### Duplicate Handling with Atomic Detection

**apps/whk-wms/src/androidSyncInbox/android-sync-inbox.service.ts (lines 39-210)**

The service uses `ON CONFLICT DO NOTHING RETURNING` to atomically identify which records were actually inserted:

```typescript
/**
 * Saves Android sync data to the inbox table using chunked processing to reduce deadlocks
 *
 * DEADLOCK MITIGATION: This method processes large batches in smaller chunks to:
 * - Reduce transaction size and lock duration
 * - Prevent all records from having identical createdAt timestamps
 * - Improve database resource utilization
 * - Enable better error isolation
 *
 * DUPLICATE HANDLING: Returns only newly created records when duplicates are encountered:
 * - Uses individual upsert operations with ON CONFLICT DO NOTHING RETURNING
 * - Atomically identifies actually inserted records without race conditions
 * - Eliminates timestamp-based queries that are prone to clock skew and race conditions
 * - Ensures return value semantics match method expectations (newly created records only)
 */
async saveToInbox(syncData: AndroidSyncDto): Promise<AndroidSyncInbox[]> {
  const { metadata, data } = syncData;
  const totalRecords = data.length;

  // ... validation ...

  try {
    // Process in chunks to avoid large transactions
    for (let i = 0; i < inboxRecords.length; i += this.CHUNK_SIZE) {
      const chunk = inboxRecords.slice(i, i + this.CHUNK_SIZE);
      const chunkNumber = Math.floor(i / this.CHUNK_SIZE) + 1;
      const totalChunks = Math.ceil(inboxRecords.length / this.CHUNK_SIZE);

      try {
        // Use individual upsert operations to reliably identify inserted records
        // This eliminates race conditions from timestamp-based queries
        const chunkInsertPromises = chunk.map(async (record) => {
          try {
            const result = await this.prisma.$queryRaw<AndroidSyncInbox[]>`
              INSERT INTO "AndroidSyncInbox" (
                "deviceName", "inboxId", "barrelSN", "locationString", 
                "eventType", "jsonEntityPayload", "operator", "createdAt", 
                "sync", "error", "warehouseJobId", "receivedAt", "updatedAt"
              ) VALUES (
                ${record.deviceName}, ${record.inboxId}, ${record.barrelSN}, ${record.locationString},
                ${record.eventType}, ${jsonPayload}::jsonb, ${record.operator}, ${record.createdAt},
                ${record.sync}, ${record.error}, ${record.warehouseJobId}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
              )
              ON CONFLICT ("deviceName", "inboxId") DO NOTHING
              RETURNING *
            `;

            // If RETURNING returns a record, it was actually inserted (not a duplicate)
            return result.length > 0 ? result[0] : null;
          } catch (error) {
            // Log individual errors
            return null;
          }
        });

        // Wait for all insertions in this chunk to complete
        const chunkResults = await Promise.all(chunkInsertPromises);

        // Filter out null results (duplicates or errors) and collect successful insertions
        const chunkInsertedRecords = chunkResults.filter(
          (record): record is AndroidSyncInbox => record !== null,
        );

        insertedRecords.push(...chunkInsertedRecords);
        totalInserted += chunkInsertedRecords.length;

        const skippedCount = chunk.length - chunkInsertedRecords.length;
        if (skippedCount > 0) {
          this.logger.debug(
            `Chunk ${chunkNumber}/${totalChunks} completed: ${chunkInsertedRecords.length} records inserted, ${skippedCount} duplicates/errors skipped`,
          );
        }

        // Add delay between chunks to reduce database pressure
        if (i + this.CHUNK_SIZE < inboxRecords.length) {
          await new Promise((resolve) =>
            setTimeout(resolve, this.CHUNK_DELAY_MS),
          );
        }
      } catch (chunkError) {
        // Continue with remaining chunks
        continue;
      }
    }
  }
}
```

**Duplicate Detection Strategy:**
- **Individual upsert per record**: Each record uses its own `ON CONFLICT DO NOTHING RETURNING` statement
- **Atomic identification**: The `RETURNING *` clause only returns rows that were actually inserted, not duplicates
- **Race-condition safe**: No timestamp-based queries that are prone to clock skew
- **Return value semantic**: Only newly inserted records are returned, duplicates are filtered out as `null`

### Chunked Processing to Prevent Deadlocks

**apps/whk-wms/src/androidSyncInbox/android-sync-inbox.service.ts (lines 17-20 & 99-177)**

The service uses chunked processing with delays to reduce lock duration:

```typescript
/** Number of records to process per chunk during batch operations to reduce database lock duration */
private readonly CHUNK_SIZE = 50;

/** Delay in milliseconds between processing chunks to reduce database pressure */
private readonly CHUNK_DELAY_MS = 100;

// In saveToInbox method:
for (let i = 0; i < inboxRecords.length; i += this.CHUNK_SIZE) {
  const chunk = inboxRecords.slice(i, i + this.CHUNK_SIZE);
  // ... process chunk ...

  // Add delay between chunks to reduce database pressure (except for last chunk)
  if (i + this.CHUNK_SIZE < inboxRecords.length) {
    await new Promise((resolve) =>
      setTimeout(resolve, this.CHUNK_DELAY_MS),
    );
  }
}
```

**Deadlock Mitigation Benefits:**
- **Reduced lock duration**: Processing 50 records at a time instead of thousands keeps locks shorter
- **Distributed timestamps**: Records in different chunks get different `receivedAt` timestamps, avoiding lock contention
- **Better resource utilization**: Smaller transactions reduce database resource pressure
- **Error isolation**: Chunk failures don't stop processing of remaining records

### Serializable Transaction with Automatic Retry

**apps/whk-wms/src/prisma/prisma.service.ts (lines 4-32 & 259-350)**

For critical operations like barrel event processing, the system uses serializable transactions with exponential backoff:

```typescript
/**
 * TRANSACTION RETRY MECHANISM
 * 
 * This service provides robust transaction handling with automatic retry for
 * PostgreSQL serializable snapshot isolation (SSI) conflicts.
 *
 * KEY FEATURES:
 * - Automatic retry with exponential backoff and jitter
 * - Detects and retries transient failures
 * - Limits retries to prevent cascading failures
 *
 * RETRYABLE ERRORS:
 * - "could not serialize access" (PostgreSQL SSI conflict)
 * - "deadlock detected" (PostgreSQL deadlock)
 * - "write conflict" (concurrent write detected)
 * - "Please retry your transaction" (Prisma retry hint)
 * - Prisma error code P2034 (write conflict)
 */

async $serializableTransaction<T>(
  fn: (prisma: Omit<PrismaClient, ...>) => Promise<T>,
  maxRetries = 20,
  timeoutMs = 15000,
): Promise<{ result: T; attempts: number }> {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const startTime = Date.now();
    this.logger.debug(
      `Starting serializable transaction attempt ${attempt}/${maxRetries} with ${timeoutMs}ms timeout`,
    );

    try {
      const result = await this.$transaction(fn, {
        timeout: timeoutMs,
        isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
      });

      const duration = Date.now() - startTime;
      this.logger.debug(
        `Serializable transaction completed successfully in ${duration}ms (attempt ${attempt}/${maxRetries})`,
      );
      return { result, attempts: attempt };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      const isPrismaWriteConflict =
        error?.code === "P2034";

      // Check if error is retryable
      const isRetryable =
        errorMessage.includes("could not serialize access") ||
        errorMessage.includes("deadlock detected") ||
        errorMessage.includes("write conflict") ||
        errorMessage.includes("Please retry your transaction") ||
        isPrismaWriteConflict;

      if (isRetryable && attempt < maxRetries) {
        // Exponential backoff with jitter
        const baseDelayMs = Math.min(1000 * Math.pow(1.5, attempt - 1), 30000);
        const jitterMs = Math.random() * baseDelayMs;
        const delayMs = Math.round(baseDelayMs + jitterMs);

        this.logger.warn(
          `Serializable transaction failed (attempt ${attempt}/${maxRetries}) after ${duration}ms, retrying in ${delayMs}ms: ${errorMessage}`,
        );

        await new Promise((resolve) => setTimeout(resolve, delayMs));
        continue;
      }

      // Non-retryable or exhausted retries
      throw error;
    }
  }
}
```

