     entityType: "RESOLUTION",   // Context for filtering
     entityId: "res_123"        // Context for filtering
   }
   ```

2. **When filter evaluates:**
   ```typescript
   filter: (payload, variables) => {
     // payload = the published object
     // variables = subscription arguments from client

     // Return true = send to this client
     // Return false = skip this client
     return (
       payload.entityType === variables.entityType &&
       payload.entityId === variables.entityId
     );
   }
