private async buildUnifiedWhere(
  filters: UnifiedBarrelFilterInput,
): Promise<{ where: any; preResolvedBarrelIds?: string[] }> {
  const where: any = {};
  const andConditions: any[] = [];

  // Default: Exclude removed barrels unless explicitly requested
  if (!filters.includeRemovedBarrels) {
    const removedDispositions = [
      EnumBarrelDisposition.Removed,
      EnumBarrelDisposition.Dumped,
      EnumBarrelDisposition.TransferredOffsite,
      EnumBarrelDisposition.Rejected,
      EnumBarrelDisposition.Orphaned,
    ];

    // Exclude PendingDeletion status unless user explicitly wants it
    const wantsPendingDeletion = 
      filters?.barrel_systemstatus === EnumBarrelSystemStatus.PendingDeletion;

    if (!wantsPendingDeletion) {
      andConditions.push({
        OR: [
          { systemStatus: { not: { equals: EnumBarrelSystemStatus.PendingDeletion } } },
          { systemStatus: null },
        ],
      });
    }

    // Similar logic for removed dispositions
    const wantsRemovedDisposition = filters?.barrel_disposition && 
      removedDispositions.includes(filters.barrel_disposition);

    if (!wantsRemovedDisposition) {
      andConditions.push({
        OR: [
          { disposition: { notIn: removedDispositions } },
          { disposition: null },
        ],
      });
    }
  }
}
