private validatePrimaryOwnerFilter(
  filter: StringNullableFilter | undefined,
  fieldName: "primaryOwnerCode" | "primaryOwnerName",
): void {
  if (!filter) return;

  const PRIMARY_OWNER_UNSUPPORTED_OPERATORS = [
    "lt", "lte", "gt", "gte", "in", "notIn",
  ];

  const usedUnsupportedOperators: string[] = [];

  for (const operator of PRIMARY_OWNER_UNSUPPORTED_OPERATORS) {
    if (filter[operator as keyof StringNullableFilter] !== undefined) {
      usedUnsupportedOperators.push(operator);
    }
  }

  if (usedUnsupportedOperators.length > 0) {
    const operatorList = usedUnsupportedOperators.join(", ");
    throw new BadRequestException(
      `Unsupported operator(s) for '${fieldName}': ${operatorList}. ` +
      `Only 'equals' and 'contains' operators are supported for primary owner filters.`,
    );
  }
}
