async dataChangeMiddleware(
  params: PrismaMiddlewareParams,
  next: (params: PrismaMiddlewareParams) => Promise<any>,
  userId?: string,
  sessionId?: string,
  correlationId?: string,
  ipAddress?: string,
  userAgent?: string,
): Promise<any> {
  // Enhanced context support - get context from request if not provided
  const context = this.contextService?.getFullContext();
  const enhancedUserId = userId || context?.userId || "system";
  const enhancedSessionId = sessionId || context?.sessionId;
  const enhancedCorrelationId = correlationId || context?.correlationId || 
                                this.generateCorrelationId();

  // Track 23 entity types (Barrel, StorageLocation, Lot, Customer, etc.)
  const trackedModels = [
    "Barrel", "StorageLocation", "Lot", "InventoryUploadSession",
    "InventoryUploadStaging", "WeightLog", "HoldingLocation",
    "Customer", "Item", "Recipe", "PurchaseOrder", "SalesOrder",
    "Transfer", "Sample", "FinancialTransaction", "GroupTransaction",
    "OwnershipTransaction", "OwnershipTransactionGroup",
    "User", "BarrelEvent", "BarrelReceipt", "Vendor",
  ];

  // Skip non-tracked models and AuditLog itself
  if (!trackedModels.includes(params.model) || params.model === "AuditLog") {
