#### **Before State Capture with Retry Logic** (lines 1287-1347)

For update/delete operations, the middleware captures the **before state** before executing the operation:

```typescript
if (params.action === "update" || params.action === "delete") {
  const beforeStateStart = Date.now();
  const maxRetries = 3;
  let retryCount = 0;

  while (retryCount < maxRetries) {
    try {
      const currentRecord = await (this.prisma as any)[
        params.model.toLowerCase()
      ].findUnique({
        where: params.args.where,
      });

      if (currentRecord) {
        beforeState = this.sanitizeForAudit(currentRecord);  // Complete entity state
        entityId = currentRecord.id;
        break; // Success, exit retry loop
      }
    } catch (error: any) {
      retryCount++;
      if (retryCount >= maxRetries) {
        // Log error but continue - don't block the operation
        this.logErrorOperation({
          operation: "beforeStateCapture",
          entityType: params.model,
          entityId: "unknown",
          userId: enhancedUserId,
          error: error,
          operationDetails: {
            prismaAction: params.action,
            model: params.model,
            retryCount,
          },
        });
      } else {
        // Exponential backoff: 2^retryCount * 100ms
        await new Promise((resolve) =>
          setTimeout(resolve, Math.pow(2, retryCount) * 100),
        );
      }
    }
  }
}
