async getAuditLogs(options: AuditLogQueryOptions = {}): Promise<AuditLog[]> {
  const where: Prisma.AuditLogWhereInput = {};

  // Multi-dimensional filtering
  if (options.operationType) {
    where.operationType = Array.isArray(options.operationType)
      ? { in: options.operationType }
      : options.operationType;
  }

  if (options.entityType) {
    where.entityType = Array.isArray(options.entityType)
      ? { in: options.entityType }
      : options.entityType;
  }

  if (options.entityId) {
    where.entityId = Array.isArray(options.entityId)
      ? { in: options.entityId }
      : options.entityId;
  }

  // Date range filtering for temporal queries
  if (options.dateFrom || options.dateTo) {
    where.createdAt = {};
    if (options.dateFrom) {
      where.createdAt.gte = options.dateFrom;
    }
    if (options.dateTo) {
      where.createdAt.lte = options.dateTo;
    }
  }

  const auditLogs = await this.prismaRead.auditLog.findMany({
    where,
    skip: options.skip,
    take: options.take,
    orderBy: options.orderBy || [{ createdAt: "desc" }],  // Chronological order
    include: {
      user: true,
      inventoryUploadSession: true,
    },
  });

  return auditLogs;
}
