async getChangeComparison(
  auditLogId: string,
): Promise<AuditChangeComparisonDto> {
  const auditLog = await this.prismaRead.auditLog.findUnique({
    where: { id: auditLogId },
  });

  if (!auditLog) {
    throw new BadRequestException(`Audit log not found: ${auditLogId}`);
  }

  // Calculate detailed field-level changes
  const fieldChanges = this.calculateFieldChanges(
    auditLog.beforeState,
    auditLog.afterState,
    auditLog.changedFields || [],
  );

  return {
    auditLogId: auditLog.id,
    operationType: auditLog.operationType,
    entityType: auditLog.entityType,
    entityId: auditLog.entityId,
    beforeState: auditLog.beforeState,          // Original complete state
    afterState: auditLog.afterState,            // Updated complete state
    changedFields: auditLog.changedFields || [],
    fieldChanges,                               // Detailed per-field changes
    timestamp: auditLog.createdAt,
    userId: auditLog.userId,
  };
}

private calculateFieldChanges(
  beforeState: any,
  afterState: any,
  changedFields: string[],
) {
  const fieldChanges: any[] = [];

  const allFields = new Set([
    ...Object.keys(beforeState || {}),
    ...Object.keys(afterState || {}),
    ...changedFields,
  ]);

  for (const field of allFields) {
    const beforeValue = beforeState?.[field];
    const afterValue = afterState?.[field];

    // Classify each field change
    let changeType: "added" | "modified" | "removed";

    if (beforeValue === undefined && afterValue !== undefined) {
      changeType = "added";
    } else if (beforeValue !== undefined && afterValue === undefined) {
      changeType = "removed";
    } else {
      changeType = "modified";
    }

    if (beforeValue !== afterValue) {
      fieldChanges.push({
        field,
        beforeValue,
        afterValue,
        changeType,        // Semantic classification
      });
    }
  }

  return fieldChanges;
}
```

