      manualTracking: true,  // Mark as manual
      ...params.operationDetails,
    },
  });
}

// Batch tracking for bulk operations
async trackDataChanges(
  changes: Array<{
    entityType: EnumAuditEntityType;
    entityId: string;
    operationType: EnumAuditOperationType;
    beforeState?: any;
    afterState?: any;
    operationDetails?: any;
  }>,
  commonParams: { userId?: string; sessionId?: string; correlationId?: string },
): Promise<AuditLog[]> {
  // All changes share same correlationId for traceability
  return this.createAuditLogs(
    changes.map((change) => ({
      // ... mapped audit log data
      correlationId: commonParams.correlationId,
    }))
  );
}
```

---

★ **Insight ────────────────────────────────────**

1. **Before/After State Snapshots Enable Full Reconstruction**: The system captures complete entity state before and after each operation (lines 1287-1373). This enables not just tracking "what changed" but also "reconstructing the entity state at any point in time by replaying operations". For example, given a barrel's entire audit history, you can determine its state on any date in the past by selecting all operations before that date and applying them sequentially.

2. **Field-Level Change Tracking Optimizes Storage and Queries**: While full JSONB states are stored for complete reconstruction, the `changedFields` array (lines 687-709) provides an indexed, queryable record of which fields changed. This allows efficient queries like "show me all barrels where the recipe field changed" without scanning entire JSONB documents. The middleware computes this at audit time (line 1433), not at query time.

3. **Correlation IDs Link Related Operations Across Entity Boundaries**: The `correlationId` field (line 1248) groups logically related changes across multiple entities. When a barrel transfer updates the Barrel record, BarrelOwnership record, and StorageLocation record in a single transaction, all three audit logs share the same `correlationId`. This enables "transaction-level" history reconstruction—viewing all changes that occurred together in a single business operation (lines 542-561).

4. **Exponential Backoff Retry Logic Ensures Before State Accuracy**: The before-state capture (lines 1287-1347) includes retry logic with exponential backoff (2^retryCount * 100ms) to handle database latency spikes. This is critical because if before-state capture fails silently, the audit trail becomes unreliable for history reconstruction. The retry count is logged, allowing debugging of database performance issues.

5. **Integrity Validation Detects Reconstruction Failures at Write Time**: The `checkConsistency()` method (lines 217-268) runs on every audit log and validates that state transitions are complete. Update operations missing beforeState or afterState are flagged as critical issues immediately, not discovered later when users try to reconstruct history. This "fail-fast" approach prevents accumulation of unusable audit records.

