} {
  const correlationId = this.requestContextService.getCorrelationId();
  const meta = this.requestContextService.getOperationMetadata() || {};
  return {
    correlationId,
    origin: typeof meta.origin === "string" ? meta.origin : undefined,
    readConsistency:
      typeof meta.readConsistency === "string" ? meta.readConsistency : undefined,
