@Cron(process.env.RAG_INDEX_CRON ?? "0 */30 6-18 * * 1-5", {
  timeZone: process.env.TZ ?? "America/Louisville",
})
async scheduledIndexing(): Promise<void> {
  // Every 30 minutes during business hours (6am-6pm) on weekdays
