```typescript
async validateCodeUniqueness(
  threeLetterCode: string,
  lotBarrelCode: string,
  excludeId?: string,
) {
  const normalizedLotBarrelCode = lotBarrelCode.toUpperCase();

  const where = excludeId
    ? {
        AND: [
          { id: { not: excludeId } },
          {
            OR: [
              { threeLetterCode: threeLetterCode.toUpperCase() },
              { lotBarrelCode: normalizedLotBarrelCode },
            ],
          },
        ],
      }
    : {
        OR: [
          { threeLetterCode: threeLetterCode.toUpperCase() },
          { lotBarrelCode: normalizedLotBarrelCode },
        ],
      };

  const existing = await this.prisma.barrelOemCode.findFirst({ where });

  if (existing) {
    if (existing.threeLetterCode === threeLetterCode.toUpperCase()) {
      throw new Error(`Three-letter code '${threeLetterCode}' is already in use`);
    }
    if (existing.lotBarrelCode === normalizedLotBarrelCode) {
      throw new Error(`Lot barrel code '${lotBarrelCode}' is already in use`);
    }
  }

  return true;
}
```

Prevents duplicate codes during creation/update, supporting partial updates via `excludeId`.

