```typescript
/**
 * Resolves the cooperage code (threeLetterCode) from a lot number.
 * Parses the lotBarrelCode from the lot number (e.g., "01" from "25G17A.01")
 */
async function getCooperageCodeFromLotNumber(
  lotNumber: string,
  prisma: PrismaService,
): Promise<string> {
  // Parse lotBarrelCode from lot number (e.g., "01" from "25G17A.01")
  // Lot format: YYGC#.##
  const parts = lotNumber.split(".");
  const lotBarrelCode = parts.length > 1 ? parts[1]?.toUpperCase() : lotNumber.slice(-2).toUpperCase();

  if (lotBarrelCode && lotBarrelCode.length === 2) {
    try {
      const oemCode = await prisma.barrelOemCode.findUnique({
        where: { lotBarrelCode: lotBarrelCode.toUpperCase() },
        select: { threeLetterCode: true },
      });

      if (oemCode) {
        logger.info(
          `Resolved cooperage code: ${lotBarrelCode} → ${oemCode.threeLetterCode}`,
        );
        return oemCode.threeLetterCode;
      }
    } catch (error) {
      logger.error(
        `Error looking up cooperage code for ${lotBarrelCode}: ${error}`,
      );
    }
  }

  // Fallback to UNK if lotBarrelCode not found
  return "UNK";
}
```

**Cooperage Resolution Pattern:**
- Parse 2-character suffix from lot number (e.g., "25G17A.**01**")
- Look up lotBarrelCode "01" in BarrelOemCode table
- Return corresponding threeLetterCode (e.g., "ISC")
- Fall back to "UNK" (Unknown) if not found

