        fromCustomerId,
        toCustomerId,
        ownershipPercentage: percentageToTransfer,
        transferReasonId,
        notes,
        operationId: options?.operationId,
        batchId: options?.batchId,
        groupId: options?.groupId,  // ✓ Links to GroupTransaction
