async bulkUpdateOwnership(
  operation: BulkOwnershipOperationInput,
  establishedBy: string,
): Promise<BulkOwnershipOperationResponse> {
  const operationId = createId();

  // Find matching barrels
  const barrels = await this.findBarrelsForBulkOwnership(operation.filter);

  // Step 1: Create GroupTransaction
  const transactionGroup = await this.createTransactionGroup(
    EnumGroupTransactionType.ADJUSTMENT,  // Ownership adjustment type
    establishedBy,
    {
      notes: operation.notes,
      transferReasonId: operation.transferReasonId,
      operationId,
      batchId: operation.batchId || `bulk_update_${operationId}`,
      metadata: operation.filter
        ? (JSON.parse(
            JSON.stringify({
              filter: operation.filter,
              replaceExisting: operation.replaceExisting,
            }),
          ) as Prisma.InputJsonValue)
        : undefined,
    },
  );

  const isJointOwnership = operation.ownerships.length > 1;

  // Step 2: Process each barrel
  for (const barrel of barrels) {
    try {
      await this.prisma.$transaction(async (tx) => {
        // End existing ownership if replacing
        if (operation.replaceExisting) {
          await tx.barrelOwnership.updateMany({
            where: {
              barrelId: barrel.id,
              validTo: null,
            },
            data: { validTo: new Date() },
          });
        }

        const jointOwnershipGroupId = isJointOwnership
          ? createId()
          : undefined;

        // Create new ownership records
        const newOwnerships = await Promise.all(
          operation.ownerships.map((ownership: OwnershipUpdate) =>
            tx.barrelOwnership.create({
              data: {
                barrelId: barrel.id,
                customerId: ownership.customerId,
                ownershipType: isJointOwnership
                  ? EnumBarrelOwnershipType.JointOwner
                  : EnumBarrelOwnershipType.SoleOwner,
                ownershipPercentage: ownership.percentage,
                jointOwnershipGroupId,
                establishedBy,
                validFrom: new Date(),
                notes: operation.notes,
              },
            }),
          ),
        );

        // Record transaction events for each ownership created
        await Promise.all(
          operation.ownerships.map((ownership: OwnershipUpdate) =>
            this.createOwnershipTransaction(
              isJointOwnership
                ? EnumOwnershipTransactionType.BULK_JOINT_ESTABLISHMENT
                : EnumOwnershipTransactionType.BULK_ESTABLISHMENT,
              barrel.id,
              establishedBy,
              {
                toCustomerId: ownership.customerId,
                ownershipPercentage: ownership.percentage,
                transferReasonId: operation.transferReasonId,
                notes: operation.notes,
                jointOwnershipGroupId,
                operationId,
                batchId: operation.batchId || `bulk_update_${operationId}`,
                groupId: transactionGroup.id,  // ✓ Link to GroupTransaction
              },
              tx,
            ),
          ),
        );
      });
