/**
 * Batch fetch customer names by IDs.
 * Returns a Map of customer ID to customer name, with "Unknown Customer" as fallback.
 * 
 * @param customerIds - Set or Array of customer IDs to fetch
 * @param context - Optional context string for error logging
 * @returns Map of customer ID to customer name
 */
private async fetchCustomerNamesByIds(
  customerIds: Iterable<string>,
  context: string = "batch fetch",
): Promise<Map<string, string>> {
  const customerNameMap = new Map<string, string>();
  const idsArray = Array.from(customerIds);

  if (idsArray.length === 0) {
    return customerNameMap;  // ← Early exit prevents unnecessary query
  }

  try {
    // Batch fetch all customer names in a single query
    const customerData = await this.prismaRead.$queryRaw<Array<{ id: string; name: string | null }>>`
      SELECT id, data->>'name' as name  -- ← PostgreSQL JSON extraction operator
      FROM "Customer" 
      WHERE id IN (${Prisma.join(idsArray)})
    `;

    // Process results and build the map
    for (const customer of customerData) {
      customerNameMap.set(customer.id, customer.name || "Unknown Customer");  // ← Null coalescing
    }

    // Handle any customers that weren't found in the database
    for (const customerId of idsArray) {
      if (!customerNameMap.has(customerId)) {
        customerNameMap.set(customerId, "Unknown Customer");  // ← Fallback for missing IDs
      }
    }
  } catch (error) {
    // If batch query fails, log and use fallback for all customers
    this.logger.warn(
      `Failed to extract customer names in ${context}: ${error instanceof Error ? error.message : String(error)}`,
    );
    for (const customerId of idsArray) {
      customerNameMap.set(customerId, "Unknown Customer");  // ← Graceful degradation on failure
    }
  }

  return customerNameMap;
}
