### **Safety Limits Service - Core Circuit Breaker**

**`apps/whk-wms/src/inventory-upload/services/safety-limits.service.ts` (lines 1-350)**
```typescript
export interface SafetyConfig {
  id: string;
  configName: string;
  maxIterationsPerSession: number;        // ← Iteration limit
  maxBatchesPerSession: number;           // ← Batch count limit
  maxProcessingTimeMinutes: number;       // ← Time limit
  maxConsecutiveEmptyBatches: number;     // ← Empty batch threshold
  maxConsecutiveErrors: number;           // ← Error threshold
  maxMemoryUsageMB: number;               // ← Memory ceiling
  batchSizeLimit: number;                 // ← Max batch size
  stalledJobTimeoutMinutes: number;       // ← Stalled job timeout
  circuitBreakerThreshold: number;        // ← Failure threshold
  circuitBreakerResetMinutes: number;     // ← Recovery time window
  enabled: boolean;
}

export interface CircuitBreakerState {
  id: string;
  sessionId: string;
  state: "closed" | "open" | "half_open";  // ← Circuit states
  failureCount: number;                     // ← Failure accumulator
  lastFailureAt?: Date;
  openedAt?: Date;
  nextRetryAt?: Date;                       // ← Recovery window
  reason?: string;
}

/**
 * Check safety limits for a session (SQL function call)
 */
async checkSafetyLimits(
  sessionId: string,
  batchNumber: number,
  consecutiveEmptyBatches = 0,
  consecutiveErrors = 0,
  startTime?: Date,
): Promise<SafetyCheckResult> {
  const result = await this.prisma.$queryRaw`
    SELECT check_processing_safety_limits(
      ${sessionId}::text,
      ${batchNumber}::integer,
      ${consecutiveEmptyBatches}::integer,
      ${consecutiveErrors}::integer,
      ${startTime || null}::timestamp
    )
  `;

  const safetyCheck = result[0].check_processing_safety_limits;

  if (!safetyCheck.canContinue) {
    this.logger.warn(`🛑 Safety limit reached for session ${sessionId}:`, {
      reason: safetyCheck.reason,
      batchNumber,
      circuitBreakerState: safetyCheck.circuitBreakerState,
    });
  }

  return safetyCheck;
}

/**
 * Get circuit breaker state (line 171-184)
 */
async getCircuitBreakerState(sessionId: string): Promise<CircuitBreakerState | null> {
  const result = await this.prisma.$queryRaw<CircuitBreakerState[]>`
    SELECT * FROM "InventoryProcessingCircuitBreaker"
    WHERE "sessionId" = ${sessionId}
    LIMIT 1
  `;
  return result.length > 0 ? result[0] : null;
}

/**
 * Trip circuit breaker (line 190-225)
 */
async tripCircuitBreaker(sessionId: string, reason: string): Promise<void> {
  const config = await this.getDefaultConfig();
  const resetMinutes = config?.circuitBreakerResetMinutes || 15;

  // Set circuit to OPEN state, record failure, schedule recovery
  await this.prisma.$executeRaw`
    INSERT INTO "InventoryProcessingCircuitBreaker" (...)
    VALUES (${sessionId}, 'open', 1, CURRENT_TIMESTAMP, ...,
            CURRENT_TIMESTAMP + INTERVAL '${resetMinutes} minutes', ${reason})
    ON CONFLICT ("sessionId") DO UPDATE SET
      "state" = 'open',
      "failureCount" = "failureCount" + 1,
      "lastFailureAt" = CURRENT_TIMESTAMP,
      "openedAt" = CURRENT_TIMESTAMP,
      "nextRetryAt" = CURRENT_TIMESTAMP + INTERVAL '${resetMinutes} minutes',
      "reason" = ${reason}
  `;

  this.logger.warn(`🔌 Circuit breaker tripped for session ${sessionId}: ${reason}`);
}

/**
 * Check resource limits (line 256-281)
 */
async checkResourceLimits(
  sessionId: string,
): Promise<{ shouldAbort: boolean; reason?: string }> {
  const config = await this.getDefaultConfig();
  if (!config || !config.enabled) {
    return { shouldAbort: false };
  }

  // Check memory ceiling
  const memoryUsage = process.memoryUsage();
  const memoryUsageMB = Math.round(memoryUsage.heapUsed / 1024 / 1024);

  if (memoryUsageMB > config.maxMemoryUsageMB) {
    this.logger.error(`🚨 Memory limit exceeded for session ${sessionId}:`, {
      current: `${memoryUsageMB}MB`,
      limit: `${config.maxMemoryUsageMB}MB`,
    });

    // TRIGGER CIRCUIT BREAKER
    await this.tripCircuitBreaker(
      sessionId,
      `Memory limit exceeded: ${memoryUsageMB}MB > ${config.maxMemoryUsageMB}MB`,
    );

    return {
      shouldAbort: true,
      reason: `Memory usage (${memoryUsageMB}MB) exceeds limit (${config.maxMemoryUsageMB}MB)`,
    };
  }

  return { shouldAbort: false };
}

/**
 * Emergency stop (line 321-331)
 */
async emergencyStop(sessionId: string, reason: string): Promise<void> {
  this.logger.error(`🚨 EMERGENCY STOP for session ${sessionId}: ${reason}`);

  // Trip circuit breaker
  await this.tripCircuitBreaker(sessionId, `Emergency stop: ${reason}`);

  // Update session status to failed
  await this.prisma.inventoryUploadSession.update({
    where: { id: sessionId },
    data: {
      sessionStatus: "failed",
      processingCompletedAt: new Date(),
      processingSummary: { emergencyStop: true, reason, stoppedAt: new Date() },
    },
  });
}
