@Injectable()
export class ResourceMonitorService {
  // Resource thresholds - Very permissive to allow processing
  private readonly MAX_ACTIVE_JOBS = 10;           // ← Job concurrency limit
  private readonly MAX_QUEUE_SIZE = 1000;          // ← Queue backlog limit
  private readonly MAX_SYSTEM_MEMORY_PERCENTAGE = 99;  // ← System memory threshold
  private readonly MAX_NODE_HEAP_PERCENTAGE = 95;      // ← Node heap threshold
  private readonly MAX_NODE_RSS_MB = 8192;             // ← 8GB RSS limit

  /**
   * Get current system resource metrics (line 47-110)
   */
  async getResourceMetrics(): Promise<ResourceMetrics> {
    try {
      // Get queue metrics
      const activeJobs = await this.processingQueue.getActive();
      const waitingJobs = await this.processingQueue.getWaiting();

      // Get system memory usage
      const totalSystemMemory = os.totalmem();
      const freeSystemMemory = os.freemem();
      const usedSystemMemory = totalSystemMemory - freeSystemMemory;
      const systemMemoryPercentage = (usedSystemMemory / totalSystemMemory) * 100;

      // Get Node.js memory usage
      const nodeMemoryUsage = process.memoryUsage();
      const nodeHeapPercentage = (nodeMemoryUsage.heapUsed / nodeMemoryUsage.heapTotal) * 100;

      // Determine if system is overloaded
      const isOverloaded = this.isSystemOverloaded(
        activeJobs.length,
        waitingJobs.length,
        systemMemoryPercentage,
        nodeHeapPercentage,
        nodeMemoryUsage.rss,
      );

      const metrics: ResourceMetrics = {
        activeJobs: activeJobs.length,
        queueWaiting: waitingJobs.length,
        memoryUsage: {
          used: Math.round(usedSystemMemory / 1024 / 1024),
          total: Math.round(totalSystemMemory / 1024 / 1024),
          percentage: Math.round(systemMemoryPercentage),
        },
        nodeMemoryUsage: {
          heapUsed: Math.round(nodeMemoryUsage.heapUsed / 1024 / 1024),
          heapTotal: Math.round(nodeMemoryUsage.heapTotal / 1024 / 1024),
          rss: Math.round(nodeMemoryUsage.rss / 1024 / 1024),
          external: Math.round(nodeMemoryUsage.external / 1024 / 1024),
          heapPercentage: Math.round(nodeHeapPercentage),
        },
        isOverloaded,
        recommendations: this.generateRecommendations(...),
      };

      return metrics;
    } catch (error) {
      this.logger.error("Failed to get resource metrics:", error);
      return {
        activeJobs: 0,
        queueWaiting: 0,
        memoryUsage: { used: 0, total: 0, percentage: 0 },
        nodeMemoryUsage: { heapUsed: 0, heapTotal: 0, rss: 0, external: 0, heapPercentage: 0 },
        isOverloaded: true,  // ← Fail safe to assume overloaded
        recommendations: ["Unable to determine system status - consider restarting"],
      };
    }
  }

  /**
   * Check if system is overloaded (line 206-220)
   */
  private isSystemOverloaded(
    activeJobs: number,
    queueWaiting: number,
    systemMemoryPercentage: number,
    nodeHeapPercentage: number,
    nodeRssBytes: number,
  ): boolean {
    const nodeRssMB = nodeRssBytes / 1024 / 1024;

    return (
      activeJobs >= this.MAX_ACTIVE_JOBS ||
      queueWaiting >= this.MAX_QUEUE_SIZE ||
      systemMemoryPercentage >= this.MAX_SYSTEM_MEMORY_PERCENTAGE ||
      nodeHeapPercentage >= this.MAX_NODE_HEAP_PERCENTAGE ||
      nodeRssMB >= this.MAX_NODE_RSS_MB
    );
  }
}
