```typescript
@Processor("inventory-processing")
export class InventoryProcessingProcessor {
  // Track consecutive empty batches and errors per session
  private readonly sessionMetrics = new Map<
    string,
    {
      consecutiveEmptyBatches: number;
      consecutiveErrors: number;
      startTime: Date;
    }
  >();

  @Process("process-inventory-session")
  async processInventorySession(
    job: Job<{ sessionId: string; batchSize: number }>,
  ): Promise<void> {
    const { sessionId, batchSize } = job.data;

    try {
      // Initialize or get session metrics
      if (!this.sessionMetrics.has(sessionId)) {
        this.sessionMetrics.set(sessionId, {
          consecutiveEmptyBatches: 0,
          consecutiveErrors: 0,
          startTime: new Date(),
        });
      }
      const metrics = this.sessionMetrics.get(sessionId)!;

      // Calculate batch number
      const processedCount = await this.prisma.inventoryUploadStaging.count({
        where: {
          uploadSessionId: sessionId,
          processingStatus: { in: ["processed", "error"] },
        },
      });
      const batchNumber = Math.floor(processedCount / batchSize) + 1;

      // ⚡ CHECK SAFETY LIMITS (line 205)
      const safetyCheck = await this.safetyLimitsService.checkSafetyLimits(
        sessionId,
        batchNumber,
        metrics.consecutiveEmptyBatches,
        metrics.consecutiveErrors,
        metrics.startTime,
      );

      if (!safetyCheck.canContinue) {
        // Circuit breaker trips → Session fails
        this.logger.error(`🛑 Safety limit reached:`, safetyCheck);

        await this.databaseProgressService.logProcessingEvent({
          sessionId,
          batchNumber,
          logLevel: "FATAL",
          logCategory: "error",
          message: "Processing halted due to safety limits",
          details: safetyCheck,
        });

        await this.progressTrackingService.completeProcessingTracking(
          sessionId,
          EnumInventoryUploadStatus.failed,
        );

        this.cleanupSessionMetrics(sessionId, "Safety limit reached");
        throw new Error(`Safety limit reached: ${safetyCheck.reason}`);
      }

      // ⚡ CHECK RESOURCE LIMITS (line 223)
      const resourceCheck = await this.safetyLimitsService.checkResourceLimits(sessionId);
      if (resourceCheck.shouldAbort) {
        await this.safetyLimitsService.emergencyStop(sessionId, resourceCheck.reason!);
        this.cleanupSessionMetrics(sessionId, "Resource limit exceeded");
        throw new Error(resourceCheck.reason);
      }

      // Process batch
      const batchResult = await this.inventoryProcessingService.processBatch(
        sessionId,
        batchSize,
      );

      // Update consecutive metrics based on batch results (line 265-288)
      if (batchResult.processedCount === 0) {
        metrics.consecutiveEmptyBatches++;
        this.logger.warn(`⚠️ Empty batch detected. Consecutive empty: ${metrics.consecutiveEmptyBatches}`);
      } else {
        metrics.consecutiveEmptyBatches = 0;
      }

      if (batchResult.errorCount > 0) {
        metrics.consecutiveErrors++;
        this.logger.warn(`⚠️ Errors detected. Consecutive errors: ${metrics.consecutiveErrors}`);
      } else {
        metrics.consecutiveErrors = 0;
        // Reset circuit breaker on successful batch
        await this.safetyLimitsService.resetCircuitBreaker(sessionId);
      }

    } catch (error) {
      this.cleanupSessionMetrics(sessionId, "Processing error");
      throw error;
    }
  }

  /**
   * Periodic cleanup (line 87-104)
   */
  private cleanupOldSessionMetrics(): void {
    const cutoffTime = new Date(Date.now() - 24 * 60 * 60 * 1000);  // 24 hours
    let cleanedCount = 0;

    for (const [sessionId, metrics] of this.sessionMetrics.entries()) {
      if (metrics.startTime < cutoffTime) {
        this.sessionMetrics.delete(sessionId);
        cleanedCount++;
      }
    }

    if (cleanedCount > 0) {
      this.logger.log(`🧹 Periodic cleanup: removed ${cleanedCount} old session metrics`);
    }
  }
}
