```typescript
export function getRepdbForwardHeaders(
  request?: HeaderForwardRequestLike,
  explicitReadConsistencyHeader?: string | null
): Record<string, string> {
  const forwarded: Record<string, string> = {};

  // 1. Read consistency hint (replica routing)
  const readConsistency =
    normalizeHeaderValue(explicitReadConsistencyHeader) ??
    normalizeHeaderValue(request?.headers.get('x-whk-read-consistency'));
  if (readConsistency) {
    forwarded['x-whk-read-consistency'] = readConsistency;  // ← Route to primary or replica
  }

  // 2. Distributed tracing correlation
  const correlationId = normalizeHeaderValue(
    request?.headers.get('x-correlation-id')
  );
  if (correlationId) {
    forwarded['x-correlation-id'] = correlationId;  // ← Track requests across services
  }

  // 3. Request tracking for debugging
  const requestId = normalizeHeaderValue(request?.headers.get('x-request-id'));
  if (requestId) {
    forwarded['x-request-id'] = requestId;
  }

  return forwarded;
}
```

**`apps/whk-wms-front-end/app/api/graphql-proxy/forward-headers.ts` (lines 1-20)**
