export async function POST(request: NextRequest) {
  try {
    // 1. Standardized user auth
    const authResult = await authenticateUserRequest(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const { body, token: userToken } = authResult;

    // 2. Direct REST endpoint call (not GraphQL)
    const backendUrl = `${process.env.NEXT_PUBLIC_BACKEND_WMS_SERVER}/api/barrels/bulk-operations`;

    // 3. Simple forwarding with minimal headers
    const response = await fetch(backendUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${userToken}`,
        ...getRepdbForwardHeaders(request),
      },
      body: JSON.stringify(body)
    });

    // 4. Pass-through response
    const data = await response.json();
    if (!response.ok) {
      console.error('❌ Backend error:', data);
      return NextResponse.json(data, { status: response.status });
    }
    return NextResponse.json(data);
  } catch (error) {
    return NextResponse.json(
      { success: false, message: error instanceof Error ? error.message : '...' },
      { status: 500 }
    );
  }
}
