### Simple Aggregation Pattern (Prisma GroupBy)
**File:** `apps/whk-wms/src/barrelAggregates/barrel-aggregates.service.ts` (lines 82-125)

```typescript
async getBarrelCountBySize(
  where: Prisma.BarrelWhereInput,
  customerCode: string | undefined,
  user: User,
): Promise<BarrelSizeCount[]> {
  // Authorization check
  this.validateCustomerScopingRequired(user, customerCode, where);

  const effectiveWhere = customerCode
    ? this.mergeCustomerCodeIntoWhere(where, customerCode)
    : where;

  // Direct Prisma groupBy - PostgreSQL handles aggregation
  const results = await this.prismaRead.barrel.groupBy({
    by: ["barrelSize"],
    where: effectiveWhere,
    _count: { id: true },
    orderBy: { _count: { id: "desc" } },
  });

  return results.map((r) => ({
    barrelSize: r.barrelSize || "Unknown",
    count: r._count.id,
  }));
}
```

Prisma's `groupBy` translates directly to SQL `GROUP BY` at the database, avoiding any JavaScript aggregation.

### Complex Aggregation with Chunking
**File:** `apps/whk-wms/src/barrelAggregates/barrel-aggregates.service.ts` (lines 1033-1100)

For filtered aggregations requiring computed fields (PGs, WGs, proof), the service uses a two-phase approach:

```typescript
async getInventoryAggregates(
  where: Prisma.BarrelWhereInput,
  customerCode: string | undefined,
  user: User,
): Promise<InventoryAggregates> {
  // Phase 1: Authorization
  this.validateCustomerScopingRequired(user, customerCode, where);
  const effectiveWhere = customerCode
    ? this.mergeCustomerCodeIntoWhere(where, customerCode)
    : where;

  const hasFilters = Object.keys(effectiveWhere).length > 0;

  // Phase 2: Fast path (no filters)
  if (!hasFilters) {
    // Direct SQL aggregation for all barrels (line 1061)
    const [totalsResult, locationResults] = await Promise.all([
      this.calculateTotalsDirectAll(),
      this.calculateByLocationDirectAll(),
    ]);
    return { ...totalsResult, byLocation: locationResults };
  }

  // Phase 3: Filtered path with chunking
  const barrelIds = await this.getFilteredBarrelIds(effectiveWhere);  // Line 1065

  if (barrelIds.length === 0) {
    return this.emptyAggregates();
  }

  // Process in chunks to avoid event loop blocking (line 1070)
  const chunks = this.chunkArray(barrelIds, ID_CHUNK_SIZE);

  const totalsResults = [];
  const locationResults: LocationChunkResult[] = [];

  for (const chunk of chunks) {
    const [chunkTotals, chunkLocations] = await Promise.all([
      this.calculateTotalsChunk(chunk),      // Chunk-scoped aggregation
      this.calculateByLocationChunk(chunk),
    ]);
    totalsResults.push(chunkTotals);
    locationResults.push(...chunkLocations);
  }

  // Merge chunk results
  const mergedTotals = this.mergeTotalsResults(totalsResults);
  const mergedLocations = this.mergeLocationResults(locationResults);

  return { ...mergedTotals, byLocation: mergedLocations };
}
```

### Filtered ID Retrieval with Validation
**File:** `apps/whk-wms/src/barrelAggregates/barrel-aggregates.service.ts` (lines 1210-1250)

Before chunking, the service validates filter size:

```typescript
private async getFilteredBarrelIds(
  where: Prisma.BarrelWhereInput,
): Promise<string[]> {
  // Count matching barrels (line 1218)
  const count = await this.prismaRead.barrel.count({ where });

  // Hard limit check (line 1223)
  if (count > MAX_BARRELS_FOR_AGGREGATION) {
    throw new GraphQLError(
      `Filter matches ${count.toLocaleString()} barrels, which exceeds the maximum of ${MAX_BARRELS_FOR_AGGREGATION.toLocaleString()}. ` +
        `Please add more filter criteria to narrow the result set.`,
      {
        extensions: {
          code: "AGGREGATION_LIMIT_EXCEEDED",
          matchedCount: count,
          maxAllowed: MAX_BARRELS_FOR_AGGREGATION,
        },
      },
    );
  }

  // Cursor-based pagination to avoid OOM (line 1240)
  const batchSize = ID_CHUNK_SIZE;
  const allIds: string[] = [];
  let cursor: string | undefined;

  while (true) {
    const barrels = await this.prismaRead.barrel.findMany({
      where,
      select: { id: true },
      take: batchSize,
      ...(cursor ? { skip: 1, cursor: { id: cursor } } : {}),
      orderBy: { id: "asc" },
    });

    if (barrels.length === 0) break;
    allIds.push(...barrels.map((b) => b.id));
    if (barrels.length < batchSize) break;
    cursor = barrels[barrels.length - 1].id;
  }

  return allIds;
}
```

The cursor-based pagination fetches IDs incrementally to prevent loading all barrel records at once, while all IDs are accumulated for chunking.

### Chunking Utility
**File:** `apps/whk-wms/src/barrelAggregates/barrel-aggregates.service.ts` (lines 1014-1021)

```typescript
private chunkArray<T>(array: T[], chunkSize: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < array.length; i += chunkSize) {
    chunks.push(array.slice(i, i + chunkSize));
  }
  return chunks;
}
```

Splits large ID arrays into 5K-sized chunks for processing.

### Direct SQL Aggregation (No Filter Fast Path)
**File:** `apps/whk-wms/src/barrelAggregates/barrel-aggregates.service.ts` (lines 1100-1150)

```typescript
private async calculateTotalsDirectAll(): Promise<{...}> {
  const result = await this.prismaRead.$queryRaw<...>`
    SELECT
      COUNT(*)::int as total_barrels,
      SUM(CASE WHEN l."bblTotal" > 0 THEN l."totalPGs" / l."bblTotal" ELSE 0 END) as total_pgs,
      SUM(CASE WHEN l."bblTotal" > 0 THEN l."totalWGs" / l."bblTotal" ELSE 0 END) as total_wgs,
      AVG(l."bblEntryProof") as avg_proof,
      COUNT(*) FILTER (WHERE b."locationId" IS NOT NULL)::int as rickhouse_count,
      COUNT(*) FILTER (WHERE b."holdingLocationId" IS NOT NULL AND b."locationId" IS NULL)::int as holding_count
    FROM "Barrel" b
    INNER JOIN "Lot" l ON b."lotId" = l.id
  `;
```

When no filters are applied, raw SQL executes in a single query, avoiding ID fetching entirely.

### Response Data Structure
**File:** `apps/whk-wms/src/barrelAggregates/dto/inventory-aggregates.dto.ts` (lines 1-44)

```typescript
