### Service Implementation - Hierarchical Job Aggregation
**File:** `apps/whk-wms/src/warehouseJobs/base/warehouse-jobs.service.ts` (lines 4490-4750)

The service aggregates staging records across parent and all child jobs:

```typescript
async getAggregatedStagingRecords(
  jobId: string,
  status?: string,
  hasIssues?: boolean,
  issueTypes?: string[],
  issueFilterLogic?: "AND" | "OR",
  issueLevels?: string[],
): Promise<{
  records: Array<any & { jobId: string; jobTitle: string; jobColor: string }>;
  count: number;
  jobSummary: Array<{
    jobId: string;
    jobTitle: string;
    jobColor: string;
    total: number;
    occupied: number;
    empty: number;
    status: string;
  }>;
}> {
  // Phase 1: Get parent job and validate it exists (line 4507)
  const parentJob = await this.prisma.warehouseJobs.findUnique({
    where: { id: jobId, deleted: false },
    select: { id: true, title: true, childJobsCount: true },
  });

  if (!parentJob) {
    throw new NotFoundException(`Warehouse job with ID ${jobId} not found`);
  }

  // Phase 2: Get all child job IDs recursively (line 4522)
  const childJobIds = await this.getChildJobIdsRecursive(jobId);
  const allJobIds = [jobId, ...childJobIds];  // Include parent

  // Phase 3: Fetch all jobs to get titles, status, and assign colors (line 4526)
  const jobs = await this.prisma.warehouseJobs.findMany({
    where: {
      id: { in: allJobIds },
      deleted: false,
    },
    select: {
      id: true,
      title: true,
      status: true,
    },
    orderBy: { createdAt: "asc" },
  });

  // Create job color mapping (line 4539)
  const jobColorMap = new Map<string, { title: string; color: any; status: string }>();
  jobs.forEach((job, index) => {
    jobColorMap.set(job.id, {
      title: job.title,
      color: this.getJobColor(index),  // Consistent color per job
      status: job.status,
    });
  });

  // Phase 4: Build where clause with multi-dimensional filtering (line 4550)
  const where: any = {
    warehouseJobId: { in: allJobIds },  // Line 4551: Include all job IDs
  };

  if (status) {
    where.processingStatus = status;  // Line 4554: Filter by PENDING, READY, etc.
  }

  if (hasIssues !== undefined) {
    where.hasIssues = hasIssues;  // Line 4558: Filter by issue presence
  }

  // Build issue filter conditions (lines 4562-4598)
  const issueConditions: any = {};

  if (issueTypes && issueTypes.length > 0) {
    issueConditions.errorType = { in: issueTypes };  // Line 4566
  }

  if (issueLevels && issueLevels.length > 0) {
    issueConditions.errorLevel = { in: issueLevels };  // Line 4570
  }

  // Apply combined filter with AND/OR logic (lines 4574-4598)
  if ((issueTypes && issueTypes.length > 0) || (issueLevels && issueLevels.length > 0)) {
    const logic = issueFilterLogic || "OR";

    if (logic === "OR") {
      // Records with ANY matching issue (line 4580)
      where.issues = {
        some: issueConditions,
      };
    } else {
      // AND logic: Records that have ALL selected issue types (line 4585)
      if (issueTypes && issueTypes.length > 0) {
        where.AND = issueTypes.map((type) => ({
          issues: {
            some: {
              errorType: type,
              ...(issueLevels && issueLevels.length > 0 && {
                errorLevel: { in: issueLevels },
              }),
            },
          },
        }));
      } else {
        where.issues = { some: issueConditions };
      }
    }
  }

  // Phase 5: Fetch staging records from all jobs with applied filters (line 4602)
  const stagingRecords = await this.prisma.inventoryCheckStaging.findMany({
    where,
    include: {
      issues: {
        orderBy: { errorLevel: "desc" },
      },
    },
    orderBy: [{ hasIssues: "desc" }, { createdAt: "asc" }],
  });

  // Phase 6: Add job context (title, color) to each record (line 4610)
  const recordsWithContext = stagingRecords.map((record) => {
    const jobContext = jobColorMap.get(record.warehouseJobId);
    return {
      ...record,
      jobId: record.warehouseJobId,
      jobTitle: jobContext?.title || "Unknown Job",
      jobColor: jobContext?.color.hex || "#6B7280",
    };
  });

  // Phase 7: Calculate job summary (count per job) (line 4620)
  const jobSummaryMap = new Map<
    string,
    { jobId: string; jobTitle: string; jobColor: string; total: number; 
      occupied: number; empty: number; status: string }
  >();

  recordsWithContext.forEach((record) => {
    if (!jobSummaryMap.has(record.jobId)) {
      const jobContext = jobColorMap.get(record.jobId);
      jobSummaryMap.set(record.jobId, {
        jobId: record.jobId,
        jobTitle: record.jobTitle,
        jobColor: record.jobColor,
        total: 0,
        occupied: 0,  // Not applicable for staging
        empty: 0,     // Not applicable for staging
        status: jobContext?.status || "PENDING",
      });
    }
    jobSummaryMap.get(record.jobId)!.total++;  // Line 4645: Increment count
  });

  const jobSummary = Array.from(jobSummaryMap.values()).sort(
    (a, b) => b.total - a.total,  // Line 4648: Sort by total count descending
  );

  return {
    records: recordsWithContext,
    count: recordsWithContext.length,
    jobSummary,
  };
}
```

### Recursive Child Job Retrieval
**File:** `apps/whk-wms/src/warehouseJobs/base/warehouse-jobs.service.ts` (lines 4278-4303)

