private async getChildJobIdsRecursive(
  parentJobId: string,
): Promise<string[]> {
  const childIds: string[] = [];

  const collectChildren = async (jobId: string): Promise<void> => {
    const children = await this.prisma.warehouseJobs.findMany({
      where: {
        parentJobId: jobId,
        deleted: false,
      },
      select: { id: true },
    });

    for (const child of children) {
      childIds.push(child.id);
      // Recursively collect grandchildren (line 4295)
      await collectChildren(child.id);
    }
  };

  await collectChildren(parentJobId);
  return childIds;  // Flattened list of all descendants
}
