    notes?: string;
    jointOwnershipGroupId?: string;
    operationId?: string;
    batchId?: string;
    groupId?: string;
  } = {},
  tx?: Prisma.TransactionClient,
) {
  const prismaClient = tx || this.prisma;

  const ownershipTransaction = await prismaClient.ownershipTransaction.create({
    data: {
      id: createId(),
      transactionType,        // ACQUISITION, TRANSFER, RELEASE, etc.
      barrelId,
      fromCustomerId: options.fromCustomerId,
      toCustomerId: options.toCustomerId,
      ownershipPercentage: options.ownershipPercentage ?? 100,
      transferReasonId: options.transferReasonId,
      notes: options.notes,
      executedBy,
      jointOwnershipGroupId: options.jointOwnershipGroupId,
      operationId: options.operationId,
      batchId: options.batchId,
      groupId: options.groupId,
    },
  });

  return ownershipTransaction;
}
```

### Ownership Lifecycle States
**File:** `apps/whk-wms/prisma/schema.prisma` (BarrelOwnership model)

The ownership model supports time-windowed states:

```
State Diagram:
┌─────────────────────────────────────────────────────────────┐
│ BarrelOwnership Record Lifecycle                             │
├─────────────────────────────────────────────────────────────┤
│                                                              │
│  establishedAt ────────> validFrom ──────> validTo         │
│  (creation time)         (ownership start) (ownership end)  │
│                          │                  │               │
│                          └──────ACTIVE──────┘               │
│                                 (validTo = NULL)            │
│                                                              │
│  When ownership transfers:                                  │
│  1. Set validTo = NOW() on old record (closes window)      │
│  2. Create new BarrelOwnership with validFrom = NOW()      │
│  3. New record starts with validTo = NULL (active)         │
│                                                              │
│  Composite unique key ensures audit trail:                 │
│  (barrelId, customerId, validFrom) = UNIQUE                │
│                                                              │
└─────────────────────────────────────────────────────────────┘
```

`★ Insight ─────────────────────────────────────`
Barrel ownership resolution implements a **lazy temporal lookup pattern** where the system defers ownership determination until query time rather than denormalizing it during event creation. This achieves three goals:

1. **Correct-as-of-now semantics**: When querying historical events, the system automatically shows current ownership even for events created months ago. If ownership changed (Customer A → Customer B), querying events shows them under Customer B's current ownership.

2. **Efficient change handling**: Ownership transfers require only two database operations—end old record (`validTo = NOW()`) and create new record (`validTo = NULL`)—without touching the thousands of related BarrelEvent records.

3. **Audit trail preservation**: The composite unique key `(barrelId, customerId, validFrom)` ensures complete ownership history is preserved. You can query `validTo IS NOT NULL` to see historical owners and when ownership ended.

The `validTo: null` filter pattern is the canonical way to determine active ownership throughout the system. Any query needing "who currently owns this barrel" must use this pattern. If a query doesn't include this filter, it will return all ownership records (current + historical), which typically isn't the intended behavior.
`─────────────────────────────────────────────────────────────`

## ANSWER TO QUESTION 62

**Trace the data flow for time zone handling in barrel events. How are Eastern timezone DST transitions handled?**

The system implements a centralized Eastern timezone conversion strategy where all dates are stored in UTC in the database, then converted to Eastern time (with DST awareness) only at the application layer. The key insight is that DST transitions are handled algorithmically at conversion time, not stored in the database, making the system resilient to DST changes.

### Data Flow Architecture

**Storage Layer (PostgreSQL):**
- All `DateTime` fields stored in UTC (PostgreSQL default behavior)
- Example: `fillDate`, `entryTime`, `eventTime`, `createdAt`

**Application Layer Conversion:**
- Dates are converted from UTC to Eastern time when:
  1. Parsing lot codes to extract fill dates
  2. Displaying events to users
  3. Comparing dates for DST-aware calculations

**Frontend Layer:**
- Receives UTC dates from API
- Browser's native timezone handling applies local timezone conversion

### DST Detection Algorithm
**File:** `apps/whk-wms/src/barrelEvent/barrelEvent.service.ts` (lines 85-142)

```typescript
/**
 * Determines if a given date is in Eastern Daylight Time (EDT) or Eastern Standard Time (EST).
 * DST in US Eastern timezone:
 * - Starts: 2nd Sunday of March at 2:00 AM
 * - Ends: 1st Sunday of November at 2:00 AM
 *
 * @param year - The year
 * @param month - The month (0-11, JavaScript convention)
 * @param day - The day of month (1-31)
 * @returns true if the date is in DST (EDT), false if in standard time (EST)
 */
private isEasternDST(year: number, month: number, day: number): boolean {
  // DST only possible between March and November (line 96)
  if (month < 2 || month > 10) {
    return false; // January, February, December are always EST
  }

  // April through October are always DST (line 101)
  if (month > 2 && month < 10) {
    return true;
  }

  // For March: Find 2nd Sunday (line 105)
  if (month === 2) {
    // Find the second Sunday of March
    const secondSunday = this.getNthSundayOfMonth(year, month, 2);
    return day >= secondSunday;  // Line 109: DST starts 2nd Sunday
  }

  // For November: Find 1st Sunday (line 113)
  if (month === 10) {
    // Find the first Sunday of November
    const firstSunday = this.getNthSundayOfMonth(year, month, 1);
    return day < firstSunday;  // Line 116: DST ends 1st Sunday
  }

  return false;
}

/**
 * Gets the day of the month for the Nth occurrence of Sunday in a given month.
 *
 * @param year - The year
 * @param month - The month (0-11, JavaScript convention)
 * @param n - Which Sunday (1 = first, 2 = second, etc.)
 * @returns The day of month (1-31) of the Nth Sunday
 */
private getNthSundayOfMonth(year: number, month: number, n: number): number {
  // Start with the first day of the month
  const firstDay = new Date(year, month, 1);
  const firstDayOfWeek = firstDay.getDay(); // 0 = Sunday, 1 = Monday, etc.

  // Calculate days until first Sunday
  const daysUntilFirstSunday = firstDayOfWeek === 0 ? 0 : 7 - firstDayOfWeek;

  // Calculate the Nth Sunday (line 137)
  const nthSunday = 1 + daysUntilFirstSunday + (n - 1) * 7;

  return nthSunday;
}
```

**Key Points:**
- **Lines 96-98**: Simple fast-path for months outside DST period
- **Lines 101-102**: April through October always have DST
- **Lines 105-109**: March DST logic - DST begins on 2nd Sunday or later
- **Lines 113-116**: November DST logic - DST ends when 1st Sunday arrives
- **Lines 123-137**: Sunday calculation handles any year/month combination

### UTC to Eastern Time Conversion
**File:** `apps/whk-wms/src/barrelEvent/barrelEvent.service.ts` (lines 3122-3150)

When parsing lot code dates into fillDate:

```typescript
if (parsedDates && parsedDates.length > 0 && parsedDates[0].filled_at) {
  // Use the parsed dates from the lot code
  // The SQL function returns dates as timestamps without timezone
  // We need to interpret them as Eastern time (midnight ET)
  const parsedFillDate = new Date(parsedDates[0].filled_at);
  const parsedEntryDate = new Date(
    parsedDates[0].entered_at || parsedDates[0].filled_at,
  );

  // The dates from the database are interpreted as UTC but represent local dates
  // We need to adjust them to represent midnight Eastern time in UTC
  // EDT is UTC-4, EST is UTC-5 (line 3131)

  // Get the year, month and day from the parsed date
  const year = parsedFillDate.getUTCFullYear();
  const month = parsedFillDate.getUTCMonth();
  const day = parsedFillDate.getUTCDate();

  // Determine if this date is in DST based on US Eastern timezone rules
  const isDST = this.isEasternDST(year, month, day);  // Line 3139
  const easternOffsetHours = isDST ? 4 : 5; // EDT is UTC-4, EST is UTC-5 (line 3140)

  // Set the dates to midnight Eastern time (which is 4 or 5 AM UTC) (line 3142)
  fillDate = new Date(
    Date.UTC(year, month, day, easternOffsetHours, 0, 0, 0),
  );
  // Entry time should be the same as fill date based on the SQL function
  entryTime = new Date(
    Date.UTC(year, month, day, easternOffsetHours, 0, 0, 0),
  );

  this.logger.debug(
    `Parsed dates from lot code ${lotNumber}: fillDate=${fillDate.toISOString()}, entryTime=${entryTime.toISOString()}`,
  );
}
```

**Conversion Logic:**
- Line 3139: `isEasternDST(year, month, day)` returns true if in EDT period
- Line 3140: `easternOffsetHours` = 4 (EDT: UTC-4) or 5 (EST: UTC-5)
- Line 3142-3148: Create new Date in UTC with the appropriate offset:
  - EDT: `Date.UTC(year, month, day, 4, 0, 0, 0)` = midnight Eastern in UTC
  - EST: `Date.UTC(year, month, day, 5, 0, 0, 0)` = midnight Eastern in UTC

