### 3. **Barrel Addition: FinancialTransaction Creation**

When adding barrels to a GroupTransaction, the service creates a FinancialTransaction and corresponding BarrelEvent:

**Pattern (apps/whk-wms/src/reconciliation/reconciliation.service.ts:964-1008)**
```typescript
if (reconciliationRecord.entityType === 'GroupTransaction' && groupTransaction) {
  // Check if barrel is already in the group
  const existingTransaction = await tx.financialTransaction.findFirst({
    where: {
      groupTransactionId: input.groupId,
      barrelId: barrelId,
    },
  });

  if (existingTransaction) {
    results.errors.push({ barrelId, error: 'Barrel is already linked to this group' });
    continue;
  }

  // Create FinancialTransaction
  const financialTransaction = await tx.financialTransaction.create({
    data: {
      groupTransactionId: input.groupId,
      sourceType: 'RECONCILIATION',
      sourceId: barrelId,
      transactionDate: new Date(),
      barrelId: barrelId,
      customerId: barrel.barrelOwnerships[0]?.customerId,
      lotId: barrel.lotId,
      direction: 'IN',
      createdBy: input.executedBy,
      metadata: {
        addedViaReconciliation: true,
        reconciliationRecordId: input.reconciliationRecordId,
        notes: input.notes,
      },
    },
  });

  // Create corresponding BarrelEvent
  await tx.barrelEvent.create({
    data: {
      barrelId: barrelId,
      eventTime: new Date(),
      groupTransactionId: input.groupId,
      notes: input.notes || 'Added via barrel count reconciliation',
      createdBy: input.executedBy,
    },
  });

  // Update affectedBarrelIds array
  await tx.groupTransaction.update({
    where: { id: input.groupId },
    data: {
      affectedBarrelIds: {
        push: barrelId,
      },
    },
  });

  results.added.push(barrelId);
}
