---

### 2. **Temporal Reconstruction with CTEs**

The service reconstructs barrel state at any point in time using window functions to find the latest audit record before that timestamp:

**Pattern (apps/whk-wms/src/barrelSnapshot/barrel-snapshot.service.ts:117-184)**
```typescript
async getBarrelSnapshot(
  configs: PaginationConfig = { page: 1, pageSize: 10 },
  filters: FiltersConfig = {},
  orderBy: OrderByConfig = {},
  pointInTime: Date = new Date(),
) {
  // Build dynamic filter and sort clauses
  const { whereClause, queryParams } = this.buildWhereClause(filters);
  const orderByClause = this.buildOrderByClause(orderBy);

  // Data query with CTE at the beginning
  const dataQuery = `
    WITH BarrelStateAtTime AS (
      WITH RankedChanges AS (
        SELECT
          barrel,
          "locationId",
          "changedAt",
          ROW_NUMBER() OVER (
            PARTITION BY barrel
            ORDER BY "changedAt" DESC     -- Latest change FIRST
          ) as rn
        FROM "BarrelAudit"
        WHERE "changedAt" <= $${queryParams.length + 1}  -- Only changes BEFORE pointInTime
      ),
      LatestAuditState AS (
        SELECT
          barrel as "id",
          "locationId" as "audit_locationId"
        FROM RankedChanges
        WHERE rn = 1  -- Take the latest audit record for each barrel
      )
      SELECT
        b.id,
        COALESCE(a."audit_locationId", b."locationId") as "locationId",
        CASE
          WHEN a."id" IS NOT NULL THEN 'AUDIT'  -- Has audit history
          ELSE 'CURRENT'                         -- Only in current barrel table
        END as "dataSource",
        b."serialNumber",
        b."barrelSize",
        ... other fields ...
      FROM "Barrel" b
      LEFT JOIN LatestAuditState a ON b.id = a."id"
      WHERE b."fillDate" <= $${queryParams.length + 1}  -- Barrel existed at pointInTime
    )
    SELECT ... FROM BarrelStateAtTime
    ${whereClause}
    ${orderByClause}
    LIMIT $${queryParams.length + 2} OFFSET $${queryParams.length + 3}
  `;

  const dataParams = [...queryParams, pointInTime, limit, offset];
  const [data, countResult] = await Promise.all([
    this.prismaRead.$queryRawUnsafe(dataQuery, ...dataParams),
    this.prismaRead.$queryRawUnsafe(countQuery, ...countParams),
  ]);

  return {
    data,
    metadata: {
      page,
      pageSize,
      totalRecords,
      totalPages,
      pointInTime,  // Return the queried point-in-time for audit trail
    },
  };
}
```

**CTE logic breakdown:**
1. **RankedChanges CTE:** Partitions BarrelAudit by barrel ID, orders by `changedAt DESC` to find latest first
2. **LatestAuditState CTE:** Extracts `rn = 1` (the single latest audit record per barrel before pointInTime)
3. **BarrelStateAtTime CTE:** LEFT JOINs with LatestAuditState to get location at that time; uses COALESCE to prefer audit location when available, falls back to current barrel location
4. **dataSource marker:** Distinguishes whether data came from audit history ('AUDIT') or current barrel table ('CURRENT')

---

### 3. **Dual-Source Inventory Composition**

For comprehensive historical queries, the service merges two data sources: audit-tracked changes and barrels that never had audit entries:

**Pattern (apps/whk-wms/src/barrelAudit/barrelAudit.service.ts:270-370)**
```typescript
const allInventoryData = await this.prismaRead.$queryRaw<any[]>`
  WITH RankedAudits AS (
    SELECT *,
      ROW_NUMBER() OVER (
        PARTITION BY "serialNumber"
        ORDER BY "changedAt" DESC  -- Most recent change first
      ) as rn
    FROM "BarrelAudit"
    WHERE "changedAt" <= ${pointInTime}
    ${customerFilter}
  ),
  LatestAudits AS (
    SELECT * FROM RankedAudits WHERE rn = 1 AND action != 'Delete'
  ),
  AuditInventory AS (
    -- Source 1: Barrels with audit history at pointInTime
    SELECT
      la.id::text,
      la.action::text,
      la.barrel::text,
      la."serialNumber"::text,
      ... all barrel fields from BarrelAudit ...
      'audit'::text as source  -- Mark as audit-sourced
    FROM LatestAudits la
    LEFT JOIN "Customer" c ON la."customerId" = c.id
    LEFT JOIN "StorageLocation" sl ON la."locationId" = sl.id
    WHERE 1=1 ${warehouseFilter} ${lotFilter} ${customerNameFilter}
  ),
  BarrelInventory AS (
    -- Source 2: Barrels that NEVER had audit entries by pointInTime
    SELECT
      CONCAT('synthetic-', b.id)::text as id,
      'Create'::text as action,
      b."serialNumber"::text as barrel,
      ... all barrel fields from Barrel table ...
      'barrel'::text as source  -- Mark as barrel-sourced
    FROM "Barrel" b
    LEFT JOIN "Customer" c ON b."customerId" = c.id
    LEFT JOIN "StorageLocation" sl ON b."locationId" = sl.id
    WHERE b."createdAt" <= ${pointInTime}
      AND NOT EXISTS (
        -- Exclude if any audit history exists
        SELECT 1 FROM "BarrelAudit" ba
        WHERE ba."serialNumber" = b."serialNumber"
        AND ba."changedAt" <= ${pointInTime}
      )
      ${customerFilter}
  )
  SELECT * FROM (
    SELECT * FROM AuditInventory
    UNION ALL
    SELECT * FROM BarrelInventory  -- Combine both sources
  ) combined
  ORDER BY "serialNumber"
  ${paginationClause}
`;
```

**Key insight:** `BarrelInventory` (Source 2) handles barrels created before `pointInTime` that never appeared in BarrelAudit, ensuring no inventory gaps in time travel queries.

---

### 4. **Inventory Count at Point-in-Time**

For pagination metadata and summary queries, counts are efficiently calculated without loading all records:

**Pattern (apps/whk-wms/src/barrelAudit/barrelAudit.service.ts:755-830)**
```typescript
async getInventoryCountAtDate(
  pointInTime: Date,
  customerIds?: string | string[],
): Promise<number> {
  const customerIdsArray = Array.isArray(customerIds) ? customerIds : [customerIds];
  const customerFilter = customerIdsArray?.length
    ? Prisma.sql`AND "customerId" IN (${Prisma.join(customerIdsArray)})`
    : Prisma.sql``;

  // Count 1: Barrels with audit history
  const result = await this.prismaRead.$queryRaw<[{ count: string }]>`
    WITH RankedAudits AS (
      SELECT *,
        ROW_NUMBER() OVER (
          PARTITION BY "serialNumber"
          ORDER BY "changedAt" DESC
        ) as rn
      FROM "BarrelAudit"
      WHERE "changedAt" <= ${pointInTime}
      ${customerFilter}
    )
    SELECT COUNT(*) as count FROM RankedAudits 
    WHERE rn = 1 AND action != 'Delete'  -- Latest audit state, exclude deletes
  `;

  // Count 2: Barrels without any audit history
  const barrelWithoutAuditsCount = await this.prismaRead.barrel.count({
    where: {
      AND: [
        {
          createdAt: { lte: pointInTime },  // Existed at pointInTime
        },
        {
          serialNumber: {
            notIn: await this.prismaRead.barrelAudit
              .findMany({
                where: {
                  changedAt: { lte: pointInTime },
                },
                select: { serialNumber: true },
                distinct: ["serialNumber"],
              })
              .then((results) => results.map((r) => r.serialNumber)),
          },
        },
        customerIdsArray?.length ? { barrelOwnerships: { ... } } : {},
      ],
    },
  });

  return parseInt(result[0].count) + barrelWithoutAuditsCount;  // Total inventory count
}
```

---

### 5. **Indexed Temporal Lookups**

BarrelAudit table uses composite and time-focused indexes to optimize point-in-time queries:

**Pattern (apps/whk-wms/apps/whk-wms/prisma/schema.prisma:751-790)**
```prisma
model BarrelAudit {
  id                    String   @id @default(cuid())
  barrel                String
  serialNumber          String
  changedAt             DateTime? @default(now())
  changedBy             String
  customerId            String?
  locationId            String?
  action                EnumBarrelAuditAction
  // ... other fields ...

  @@index([serialNumber, changedAt(sort: Desc)])  // PIT query optimization
  @@index([changedAt])                             // Time-range filtering
  @@index([customerId, changedAt])                 // Customer + time filtering
}
```

**Index strategy:**
- `[serialNumber, changedAt DESC]` - Primary index for "get latest state for each barrel" queries
- `[changedAt]` - Enables fast range filtering (`WHERE changedAt <= pointInTime`)
- `[customerId, changedAt]` - Supports customer-specific historical queries

---

### 6. **Inventory Snapshots with Aggregation**

The service also supports aggregated inventory snapshots across multiple time periods:

**Pattern (apps/whk-wms/src/barrelAudit/barrelAudit.service.ts:55-103)**
```typescript
async getInventorySnapshots(
  startDate: Date,
  endDate: Date = new Date(),
  period: AggregationPeriod = "month",  // DAY, WEEK, MONTH, QUARTER, YEAR
  customerIds?: string | string[],
  includeBarrels = false,
  page = 1,
  pageSize = 100,
): Promise<InventorySnapshot[]> {
  const periodDates = this.generatePeriodDates(startDate, endDate, period);  // Generate boundaries
  const snapshots: InventorySnapshot[] = [];

  for (const date of periodDates) {
    if (includeBarrels) {
      // Load detailed inventory at each period boundary
      const inventory = await this.getInventoryAtDate(date, customerIdsArray);
      const paginatedBarrels = inventory.slice(
        (page - 1) * pageSize,
        page * pageSize,
      );

      snapshots.push({
        period: this.formatPeriod(date, period),     // "2025-01", "2025-Q1", etc.
        periodStartDate: date,
        periodType: period,
        count: inventory.length,
        barrels: paginatedBarrels,
      });
    } else {
      // Just get counts for efficiency
      const count = await this.getInventoryCountAtDate(date, customerIdsArray);
      snapshots.push({
        period: this.formatPeriod(date, period),
        periodStartDate: date,
        periodType: period,
        count: count,
      });
    }
  }

  return snapshots;
}
```

---

### **Summary: Point-in-Time Query Architecture**

```
┌─────────────────────────────────────────────────────────────────┐
│ API Request: GET /barrel-audit-table?pointInTime=2024-06-15T00:00Z
└──────────────────────────────────┬──────────────────────────────┘
                                   │
                    ┌──────────────▼───────────────┐
                    │ Parse pointInTime parameter  │
                    └──────────────┬───────────────┘
                                   │
        ┌──────────────────────────▼──────────────────────────┐
        │ Query Construction with Three CTEs                  │
        │                                                      │
        │ 1. RankedChanges: Rank audit events per barrel      │
        │    WHERE changedAt <= pointInTime                   │
        │                                                      │
        │ 2. LatestAuditState: Extract rn=1 (most recent)    │
        │                                                      │
        │ 3. BarrelStateAtTime: LEFT JOIN barrels with audit  │
        │    state, COALESCE location, mark dataSource        │
        │                                                      │
        │ UNION ALL: Add barrels with NO audit history        │
        │    (WHERE created <= pointInTime AND NOT IN audit)  │
        └──────────────────────────────────────────────────────┘
                           │
        ┌──────────────────▼──────────────────┐
        │ Execute Optimized SQL               │
        │                                      │
        │ Uses Indexes:                        │
        │ - [serialNumber, changedAt DESC]    │
        │ - [changedAt]                        │
        │ - [customerId, changedAt]           │
        │                                      │
        │ Query Execution:                     │
        │ - Window function rank              │
        │ - LEFT JOINs to metadata tables      │
        │ - UNION ALL deduplication           │
        │ - Apply filters & sorting           │
        │ - Pagination (LIMIT/OFFSET)         │
        └──────────────┬───────────────────────┘
                       │
        ┌──────────────▼──────────────────┐
        │ Return Results                   │
        │ - data: barrel snapshots         │
        │ - metadata.pointInTime           │
        │ - metadata.totalPages            │
        └──────────────────────────────────┘
```

| Feature | Implementation |
|---------|-----------------|
| **Temporal Reconstruction** | CTE with ROW_NUMBER() OVER (... ORDER BY changedAt DESC) |
| **Dual Sources** | UNION ALL of BarrelAudit (tracked) + Barrel (untracked) |
| **Time Range Filtering** | WHERE changedAt <= $pointInTime on both sources |
| **Efficient Counting** | Separate query with UNION logic to count both sources |
| **Filtering & Sorting** | Dynamic SQL with parameterized WHERE/ORDER BY clauses |
| **Pagination** | LIMIT/OFFSET on final combined result set |
| **Delete Handling** | WHERE action != 'Delete' to exclude deleted barrels |
| **Aggregation** | Snapshot generation across time periods (DAY/WEEK/MONTH/etc.) |

## ANSWER: Question 77 - BullMQ Processor Configuration Differences

AndroidSyncProcessor and InventoryCheckStagingProcessor have significantly different BullMQ concurrency and rate limiting options reflecting their distinct transaction requirements and data flow positions. AndroidSyncProcessor prioritizes controlled sequential processing due to serializable transactions, while InventoryCheckStagingProcessor uses higher concurrency with standard write operations.

---

### 1. **Concurrency: 2 vs 5 (Primary Difference)**

**AndroidSyncProcessor (apps/whk-wms/src/androidSyncInbox/android-sync.processor.ts:40-46)**
```typescript
@Processor("android-sync-processing", {
  concurrency: 2, // TEC-839: Limit to 2 devices uploading simultaneously
  lockDuration: 120000, // 2 minutes - longer jobs need more time
  stalledInterval: 30000, // Check for stalled jobs every 30 seconds
  maxStalledCount: 3,
  limiter: { max: 20, duration: 1000 }, // Rate limit: 20 jobs/second
})
export class AndroidSyncProcessor extends WorkerHost implements OnModuleInit {
```

**InventoryCheckStagingProcessor (apps/whk-wms/apps/whk-wms/src/staging/inventory-check-staging.processor.ts:30-36)**
```typescript
@Processor("inventory-check-staging", {
  concurrency: 5, // Match original concurrency
  lockDuration: 120000, // 2 minutes - longer jobs need more time
  stalledInterval: 30000, // Check for stalled jobs every 30 seconds
  maxStalledCount: 3,
  limiter: { max: 10, duration: 1000 }, // Rate limit: 10 jobs/second
})
export class InventoryCheckStagingProcessor extends WorkerHost implements OnModuleInit {
```

**Rationale:**
- **2 concurrent devices** (AndroidSyncProcessor): Uses `$serializableTransaction` which creates strict SSI locks on multiple tables (Barrel, BarrelEvent, BarrelAudit, Location). Limiting to 2 prevents deadlocks and transaction conflicts when multiple devices upload simultaneously (TEC-839)
- **5 concurrent records** (InventoryCheckStagingProcessor): Performs upsert/update operations without serializable isolation, allowing higher parallelism safely

---

### 2. **Rate Limiting: 20 vs 10 Jobs per Second**

**AndroidSyncProcessor limiter: 20 jobs/second**
- Devices continuously upload records; higher throughput needed at queue entry point
- Records pass through quickly without heavy CPU/I/O work before queuing
- Acts as a burst absorber for device uploads

**InventoryCheckStagingProcessor limiter: 10 jobs/second**
- Each job performs validation, issue detection, and database upserts
- Validates barrel scans against multiple criteria (BAD_QR, NOLABEL, duplicates)
- Lower rate prevents queue bloat during validation-heavy operations

---

### 3. **Transaction Strategy Differences**

**AndroidSyncProcessor uses SERIALIZABLE transactions (apps/whk-wms/apps/whk-wms/src/androidSyncInbox/android-sync.processor.ts:467-550)**
```typescript
private async processRecordWithBusinessLogic(eventData: any): Promise<void> {
  const isLocationCritical = this.isLocationCriticalOperation(eventData);

  if (isLocationCritical) {
    // Use serializable transaction for location-critical operations
    await this.processWithSerializableTransaction(eventData);
  } else {
    // Use regular Android sync transaction
    await this.processWithAndroidSyncTransaction(eventData);
  }
}

private async processWithSerializableTransaction(
  eventData: any,
): Promise<void> {
  let bruteForceWarningToLog: any = null;

  try {
    await this.prisma.$serializableTransaction(async (tx) => {
      const result =
        await this.barrelEventService.createBarrelEventWithLocationAndLocationCheck(
          eventData,
          tx,
        );

      // TEC-1173: Capture bruteForceWarningToLog for logging after transaction
      if ((result as any)?.bruteForceWarningToLog) {
        bruteForceWarningToLog = (result as any).bruteForceWarningToLog;
      }

      await this.androidSyncInboxService.markAsSynced(
        eventData.deviceName,
        eventData.inboxId,
        tx,
      );
    });

    // TEC-1173: Log BarrelCreatedByBruteForce warning AFTER transaction commits
    if (bruteForceWarningToLog) {
      await this.androidSyncErrorLoggerService.logError({ ... });
    }
  }
}
```

**InventoryCheckStagingProcessor uses standard write operations (apps/whk-wms/apps/whk-wms/src/staging/inventory-check-staging.processor.ts:160-280)**
```typescript
async process(job: Job<StagingJobData>): Promise<void> {
  try {
    // Step 1: Fetch the AndroidSyncInbox record
    const inboxRecord = await this.prisma.androidSyncInbox.findUnique({
      where: { deviceName_inboxId: { deviceName, inboxId } },
    });

    // Step 2: Create or update staging record WITHOUT serializable transaction
    const staging = await this.prisma.inventoryCheckStaging.upsert({
      where: {
        warehouseJobId_inboxDeviceName_inboxId: {
          warehouseJobId: jobId,
          inboxDeviceName: deviceName,
          inboxId,
        },
      },
      create: {
        warehouseJobId: jobId,
        barrelSerialNumber: inboxRecord.barrelSN || "",
        locationString: inboxRecord.locationString || "",
        processingStatus: InventoryCheckStagingStatus.PROCESSING,
        processingStartedAt: now,
        lastHeartbeat: now,
        bullJobId: job.id?.toString() || "",
        processingAttempts: 1,
      },
      update: {
        barrelSerialNumber: inboxRecord.barrelSN || "",
        processingStatus: InventoryCheckStagingStatus.PROCESSING,
        processingStartedAt: now,
        lastHeartbeat: now,
        bullJobId: job.id?.toString() || "",
        processingAttempts: { increment: 1 },
      },
    });

    // Step 3: Run validation and issue detection (no serializable tx)
    await this.validateAndDetectIssues(staging.id);

    // Step 4: Mark as ready without transaction overhead
    await this.prisma.inventoryCheckStaging.update({
      where: { id: staging.id },
      data: {
        processingStatus: InventoryCheckStagingStatus.READY,
        processingStartedAt: null,
      },
    });
  }
}
```

---

### 4. **Cache Warming Strategy**

**AndroidSyncProcessor warms caches at initialization (apps/whk-wms/apps/whk-wms/src/androidSyncInbox/android-sync.processor.ts:77-112)**
```typescript
