function categorizeError(error: Error, errorId: string): CategorizedError {
  let errorMessage = `Resolution failed for error ${errorId}: ${error.message}`;
  let errorCategory = "UNKNOWN_ERROR";

  // Lines 26–31: RESOURCE_NOT_FOUND
  if (error.message?.includes("not found") || 
      error.message?.includes("does not exist")) {
    errorCategory = "RESOURCE_NOT_FOUND";
    // Redact internal details, provide generic message
    errorMessage = `Resource not found during resolution: ${error.message}`;
  }

  // Lines 32–42: RESOURCE_CONFLICT
  else if (error.message?.includes("already exists") ||
           error.message?.includes("conflict")) {
    errorCategory = "RESOURCE_CONFLICT";
    if (error.message?.includes("already occupied")) {
      // Line 39: Client-safe message without exposing internal state
      errorMessage = `Location is currently occupied by another barrel. 
                     Please choose a different resolution option or verify 
                     the target location. Details: ${error.message}`;
    }
  }

  // Lines 43–48: PERMISSION_ERROR
  else if (error.message?.includes("permission")) {
    errorCategory = "PERMISSION_ERROR";
    errorMessage = `Permission denied during resolution: ${error.message}`;
  }

  // Lines 49–59: VALIDATION_ERROR
  else if (error.message?.includes("validation") ||
           error.message?.includes("invalid")) {
    errorCategory = "VALIDATION_ERROR";
    errorMessage = `Validation failed during resolution: ${error.message}`;
  }

  return { errorMessage, errorCategory };
}
