private formatValidationErrorMessage(message: string): string {
  const unknownArgMatch = message.match(/Unknown argument `(\w+)`/);
  if (unknownArgMatch) {
    const fieldName = unknownArgMatch[1];
    // Only expose field name, not type/schema information
    return `Invalid request data: '${fieldName}' field is not supported or has been removed from the API.`;
  }

  // Generic fallback - don't expose schema details
  return "Invalid request data: Please check your input parameters and try again.";
}
