@Catch()
export class SentryExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost): void {
    // Lines 15–27: Patterns to EXCLUDE from Sentry
    const INFRASTRUCTURE_ERROR_PATTERNS = [
      /EPIPE/i,
      /ECONNRESET/i,
      /ECONNREFUSED/i,
      /ETIMEDOUT/i,
    ];

    function isInfrastructureError(message: string): boolean {
      return INFRASTRUCTURE_ERROR_PATTERNS.some(pattern => pattern.test(message));
    }

    // Lines 50–56: Determine if error should be sent to Sentry
    const isHttpException = exception instanceof HttpException;
    const isClientError = status >= 400 && status < 500;
    const shouldCapture =
      !isInfrastructureError(message) &&        // ❌ Don't send transient errors
      !(isHttpException && isClientError);      // ❌ Don't send 4xx errors (user input validation)

    if (shouldCapture) {
      // Lines 59–65: Send MINIMAL context to external service
      Sentry.captureException(exception, {
        extra: {
          path: request?.path || 'unknown',     // URL path only
          method: request?.method || 'unknown', // HTTP method only
          statusCode: status,                    // Status code only
          // ❌ NEVER include: request body, headers, query params, sensitive fields
        },
      });
    }

    // Lines 74–82: Return generic message to client
    response.status(status).json({
      statusCode: status,
      message:
        exception instanceof HttpException
          ? exception.message
          : "Internal server error",           // Generic message for 5xx errors
      timestamp: new Date().toISOString(),
      path: request?.path || 'unknown',
    });
  }
}
```

