### **DISTRIBUTED CACHE INVALIDATION** (Lines 56–92, 186–245, `cached-event-type.service.ts`)

**Redis Pub/Sub for Multi-Instance Synchronization:**

```typescript
// Subscribe to distributed invalidation events on module init (lines 56–92)
async onModuleInit(): Promise<void> {
  if (!this.pubSubProvider) {
    this.logger.log("Skipping distributed cache subscription (no Redis)");
    return;
  }

  try {
    const pubSub = this.pubSubProvider.getInstance();
    // Background listener for invalidation events
    const iterator = pubSub.asyncIterableIterator<{
      typeId: string;
      timestamp: number;
    }>(this.CACHE_INVALIDATION_CHANNEL) as AsyncIterableIterator<...>;

    // Process events asynchronously (non-blocking)
    (async () => {
      for await (const event of iterator) {
        this.handleDistributedInvalidation(event);  // Line 76
      }
    })().catch(...);  // Line 78
  }
}

// Public API: Invalidate type locally + distributed (lines 186–189)
invalidateType(typeId: string): void {
  this.performLocalInvalidation(typeId);              // Line 187
  this.emitDistributedInvalidation(typeId);           // Line 188
}

// Local invalidation: Remove ALL name variants (lines 197–220)
private performLocalInvalidation(typeId: string): void {
  // Find ALL name variants associated with this type ID (TEC-1196)
  const nameVariants = this.idToNameMap.get(typeId);  // Line 199

  if (!nameVariants || nameVariants.size === 0) {
    this.logger.debug(`No cache entries found for event type ID: ${typeId}`);
    return;
  }

  // Delete ALL cache entries for all name variants
  // e.g., if eventType.id = "evt-123", delete cached entries for:
  // - "Entry" (PascalCase)
  // - "ENTRY" (uppercase)
  // - "entry" (lowercase)
  // - "relocate" (alias)
  let deletedCount = 0;
  for (const name of nameVariants) {
    this.eventTypeCache.delete(name);       // Line 209
    this.cacheTimestamps.delete(name);      // Line 210
    deletedCount++;
  }

  // Remove the ID mapping
  this.idToNameMap.delete(typeId);          // Line 215

  this.logger.debug(
    `Locally invalidated cache for event type ID ${typeId}: removed ${deletedCount} variant(s)`,
  );
}

// Distributed invalidation: Emit to Redis (lines 225–245)
private async emitDistributedInvalidation(typeId: string): Promise<void> {
  if (!this.pubSubProvider) {
    return; // No Redis, skip distributed invalidation
  }

  try {
    const pubSub = this.pubSubProvider.getInstance();
    await pubSub.publish(this.CACHE_INVALIDATION_CHANNEL, {
      typeId,
      timestamp: Date.now(),
    });  // Lines 232–235

    this.logger.debug(
      `Published distributed invalidation for event type: ${typeId}`,
    );
  }
}

// Handle incoming distributed events (lines 250–260)
private handleDistributedInvalidation(event: {
  typeId: string;
  timestamp: number;
}): void {
  this.logger.debug(
    `Received distributed invalidation for event type: ${event.typeId}`,
  );

  // Perform local invalidation only (don't re-publish to prevent loops)
  this.performLocalInvalidation(event.typeId);  // Line 259
}
```

**Invalidation Flow:**

```
Backend Instance A                Redis Channel               Backend Instance B
     ↓                          cache:invalidate:event-type              ↓
   Update EventType              
     ↓
 invalidateType("evt-123")
     ↓
 performLocalInvalidation()   ←→  Pub: {typeId: "evt-123", ts}  ←→  handleDistributedInvalidation()
     ↓                                                                      ↓
 Delete: "Entry",            ←→  Async Iterator                  Delete: "Entry",
 "ENTRY", "entry"               (background process)            "ENTRY", "entry"
     ↓                                                                      ↓
