## Bulk Transfer Orchestration

**apps/whk-wms/src/barrelOwnership/barrelOwnership.service.ts:771-855**

For batch partial transfers:

```typescript
async bulkTransferOwnership(
  operation: BulkTransferOwnershipInput,  // Includes transferPercentage
  transferredBy: string,
): Promise<BulkOwnershipOperationResponse> {
  const operationId = createId();

  // Line 781: Query matching barrels
  const barrels = await this.findBarrelsForBulkOwnership(operation.filter);

  // Line 786-802: Create transaction group for batch coordination
  const transactionGroup = await this.createTransactionGroup(
    EnumGroupTransactionType.OWNERSHIP_TRANSFER,
    transferredBy,
    {
      fromCustomerId: operation.fromCustomerId,
      toCustomerId: operation.toCustomerId,
      notes: operation.notes,
      transferReasonId: operation.transferReasonId,
      operationId,  // Links all transfers together
      batchId: operation.batchId || `bulk_transfer_${operationId}`,
      metadata: operation.filter,  // Audit trail
    },
  );

  let barrelsCompleted = 0;
  let transactionsCreated = 0;

  // Line 807-844: Process each barrel independently
  for (const barrel of barrels) {
    try {
      await this.transferOwnership(
        barrel.id,
        operation.fromCustomerId,
        operation.toCustomerId,
        transferredBy,
        operation.transferPercentage,  // Same percentage for all
        operation.notes,
        operation.transferReasonId,
        {
          groupId: transactionGroup.id,  // All linked to group
          operationId,
          batchId: operation.batchId || `bulk_transfer_${operationId}`,
        },
      );

      successes.push({
        barrelId: barrel.id,
        serialNumber: barrel.serialNumber,
        operation: "transfer",
      });

      barrelsCompleted += 1;
      transactionsCreated += 1;
    } catch (error) {
      // Line 833-842: Collect errors, continue processing
      this.logger.error(
        `Failed to transfer ownership for barrel ${barrel.id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      errors.push({
        barrelId: barrel.id,
        serialNumber: barrel.serialNumber,
        error: "Transfer failed",
        details: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return {
    totalRequested: barrels.length,
    successfulUpdates: successes.length,
    failedUpdates: errors.length,
    successes,
    errors,
    operationId,
    completedAt: new Date(),
  };
}
```

**Batch properties:**
- Line 775: Unique operationId groups all transfers
- Line 786-802: GroupTransaction created once for batch
- Line 807-844: Each barrel processes independently with same groupId
- Partial failures don't block remaining barrels

