## Progress Calculation (Real-time Status)

**apps/whk-wms/src/inventory-upload/services/micro-batch-orchestrator.service.ts:566-613**

Calculates progress from checkpoint data:

```typescript
private async calculateProgress(sessionId: string): Promise<SessionProgress> {
  const session = await this.prisma.inventoryUploadSession.findUnique({
    where: { id: sessionId },
    select: { totalRows: true },
  });

  // Count rows by their current processing status
  const counts = await this.prisma.inventoryUploadStaging.groupBy({
    by: ["processingStatus"],
    where: { uploadSessionId: sessionId },
    _count: true,
  });                                              // Lines 569-576

  const totalRows = session?.totalRows || 0;
  const validatedRows =
    counts.find((c) => c.processingStatus === "validated")?._count || 0;

  // TRUST MODE FIX: Include trust_mode_skipped in processed count
  const processedRows = counts
    .filter((c) =>
      ["processed", "error", "trust_mode_skipped"].includes(
        c.processingStatus,
      ),
    )
    .reduce((sum, c) => sum + c._count, 0);       // Lines 587-595

  const errorRows =
    counts.find((c) => c.processingStatus === "error")?._count || 0;

  const progressPercentage =
    totalRows > 0 ? Math.round((processedRows / totalRows) * 100) : 0;
                                                   // Lines 599-600

  // Determine phase based on progress
  return {
    totalRows,
    validatedRows,
    processedRows,
    errorRows,
    currentPhase:
      processedRows === totalRows
        ? "completed"
        : validatedRows > 0
          ? "processing"
          : "validating",
    progressPercentage,
  };
}
```

**Returns SessionProgress**:
```typescript
interface SessionProgress {
  totalRows: number
  validatedRows: number
  processedRows: number
  errorRows: number
  currentPhase: "validating" | "processing" | "completed"
  progressPercentage: number
}
```

