private async finalizeSession(
  sessionId: string,
  message: string,
): Promise<void> {
  const progress = await this.calculateProgress(sessionId);

  // Determine final status
  const finalStatus =
    progress.errorRows > 0 && progress.processedRows === 0
      ? "failed"
      : "completed";

  await this.prisma.inventoryUploadSession.update({
    where: { id: sessionId },
    data: {
      sessionStatus: finalStatus,
      progressPercentage: 100,                      // Line 635: Mark complete
      processingCompletedAt: new Date(),            // Line 636: End timestamp
      processingSummary: {
        message,                                    // Human-readable reason
        totalRows: progress.totalRows,              // Final counts
        validatedRows: progress.validatedRows,
        processedRows: progress.processedRows,
        errorRows: progress.errorRows,
        progressPercentage: progress.progressPercentage,
      },
    },
  });
}
```

